parameters.jsCode:
return [{
  json: {
    production_request: {
      schema_version: '1.0.0',
      production_id: 'ccg-smoke-20260730-001',
      content_id: 'ccg-smoke-story-001',
      campaign_id: 'ccg-smoke-campaign-001',
      content_type: 'STATIC_SINGLE',
      production_tier: 'FAST',
      objective: 'Validar o contrato, a governança e o roteamento do Campaign Creative Generator sem efeitos externos.',
      funnel_stage: 'consideration',
      audience: {
        segment: 'fixture',
        location: 'Brasil'
      },
      procedure_or_topic: 'cuidados faciais',
      offer: {},
      cta: 'Saiba mais',
      requested_deliverables: [
        {
          deliverable_id: 'fixture-story-001',
          format: '9:16',
          usage: 'ORGANIC'
        }
      ],
      source_assets: [],
      brand_assets: [],
      references: [],
      mandatory_elements: [
        'Logo da marca',
        'CTA legível'
      ],
      forbidden_elements: [
        'Promessa garantida'
      ],
      provider_policy: {
        mode: 'mock',
        mock_provider: true,
        allowed_providers: ['mock'],
        max_cost: 0,
        max_jobs: 1,
        max_revisions: 0,
        require_human_approval: true
      },
      budget: {
        currency: 'BRL',
        max_cost: 0
      },
      dry_run: true,
      brand_context: {
        brand_name: 'Espaço Facial',
        locale: 'pt-BR',
        country: 'BR',
        compliance_profile: 'SKINCOS_AESTHETICS_BR_V1'
      },
      organizer_context: {
        source: 'n8n-manual-smoke',
        requested_by: 'operator',
        fixture: true
      }
    }
  }
}];

const items = $input.all();
if (!items.length) {
  throw new Error('[CCG-00/INPUT] Nenhum item recebido.');
}

const sourceItem = items[0] || {};
const root = sourceItem.json || {};

function isPlainObject(value) {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}

function text(value, fallback = '') {
  if (value === undefined || value === null) return fallback;
  return String(value).trim();
}

function parseJson(value, label) {
  try {
    return JSON.parse(value);
  } catch (error) {
    throw new Error(`[CCG-00/INPUT] ${label} deve conter JSON válido: ${error.message}`);
  }
}

function arrayValue(value, fallback = []) {
  if (Array.isArray(value)) return value;
  if (value === undefined || value === null || value === '') return fallback;
  if (typeof value === 'string') {
    const trimmed = value.trim();
    if (!trimmed) return fallback;
    if (trimmed.startsWith('[')) {
      const parsed = parseJson(trimmed, 'campo em formato de lista');
      return Array.isArray(parsed) ? parsed : fallback;
    }
    return trimmed.split(',').map((entry) => entry.trim()).filter(Boolean);
  }
  return fallback;
}

function booleanValue(value) {
  if (typeof value === 'boolean') return value;
  if (typeof value === 'string') {
    const normalized = value.trim().toLowerCase();
    if (normalized === 'true') return true;
    if (normalized === 'false') return false;
  }
  return value;
}

let request;
if (typeof root.production_request === 'string') {
  request = parseJson(root.production_request, 'production_request');
} else if (isPlainObject(root.production_request)) {
  request = { ...root.production_request };
} else {
  request = { ...root };
}

if (!isPlainObject(request)) {
  throw new Error('[CCG-00/INPUT] production_request deve ser um objeto JSON.');
}

const requestedFormats = arrayValue(
  request.requested_formats ??
  request.formats ??
  request.organizer_context?.requested_formats
);

let requestedDeliverables = arrayValue(request.requested_deliverables);
if (!requestedDeliverables.length && requestedFormats.length) {
  requestedDeliverables = requestedFormats.map((format, index) => ({
    deliverable_id: `${text(request.content_id, 'content')}-${index + 1}`,
    format: text(format),
    usage: 'ORGANIC'
  }));
}

const providerPolicy = isPlainObject(request.provider_policy)
  ? { ...request.provider_policy }
  : {};

const budget = isPlainObject(request.budget)
  ? { ...request.budget }
  : {};

const brandContext = isPlainObject(request.brand_context)
  ? { ...request.brand_context }
  : {};

const organizerContext = isPlainObject(request.organizer_context)
  ? { ...request.organizer_context }
  : {};

const normalized = {
  ...request,
  schema_version: text(request.schema_version),
  production_id: text(request.production_id),
  content_id: text(request.content_id),
  campaign_id: text(request.campaign_id),
  content_type: text(request.content_type).toUpperCase(),
  production_tier: text(request.production_tier).toUpperCase(),
  objective: text(request.objective),
  cta: text(request.cta),
  dry_run: booleanValue(request.dry_run),

  funnel_stage: text(request.funnel_stage, 'consideration').toLowerCase(),
  procedure_or_topic: text(request.procedure_or_topic),
  audience: isPlainObject(request.audience) ? request.audience : {},
  offer: isPlainObject(request.offer) ? request.offer : {},

  requested_deliverables: requestedDeliverables,
  requested_formats: requestedFormats,

  source_assets: arrayValue(request.source_assets),
  brand_assets: arrayValue(request.brand_assets),
  references: arrayValue(request.references),
  mandatory_elements: arrayValue(request.mandatory_elements),
  forbidden_elements: arrayValue(request.forbidden_elements),

  provider_policy: {
    ...providerPolicy,
    mode: text(providerPolicy.mode).toLowerCase(),
    allowed_providers: arrayValue(providerPolicy.allowed_providers),
    max_cost: providerPolicy.max_cost ?? budget.max_cost ?? null,
    max_jobs: providerPolicy.max_jobs ?? null,
    max_revisions: providerPolicy.max_revisions ?? null
  },

  budget,
  brand_context: {
    brand_name: text(
      brandContext.brand_name ??
      request.brand_name ??
      request.brand,
      'Espaço Facial'
    ),
    unit: text(brandContext.unit ?? organizerContext.unit),
    locale: text(brandContext.locale, 'pt-BR'),
    country: text(brandContext.country, 'BR'),
    compliance_profile: text(
      brandContext.compliance_profile,
      'SKINCOS_AESTHETICS_BR_V1'
    ),
    ...brandContext
  },

  organizer_context: {
    source: text(organizerContext.source, 'skincos-orchestrator'),
    requested_by: text(organizerContext.requested_by),
    correlation_id: text(organizerContext.correlation_id),
    ...organizerContext
  },

  source_folder_id: text(
    request.source_folder_id ??
    request.source_drive_folder_id
  ),
  output_folder_id: text(
    request.output_folder_id ??
    request.output_drive_folder_id
  ),

  received_at: text(request.received_at, new Date().toISOString())
};

return [{
  json: {
    ...root,
    ...normalized,
    production_request: normalized,
    ccg_input: {
      received_items: items.length,
      used_item_index: 0,
      input_shape: root.production_request !== undefined
        ? 'production_request'
        : 'root',
      normalized_at: new Date().toISOString()
    }
  },
  binary: sourceItem.binary
}];

const item = $input.first();
const data = item.json || {};
const request = data.production_request || data;

function isPlainObject(value) {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}

function text(value) {
  if (value === undefined || value === null) return '';
  return String(value).trim();
}

function finiteNumber(value) {
  if (value === undefined || value === null || value === '') return null;
  const number = Number(value);
  return Number.isFinite(number) ? number : null;
}

const errors = [];
const warnings = [];

const required = [
  'schema_version',
  'production_id',
  'content_id',
  'campaign_id',
  'content_type',
  'production_tier',
  'objective',
  'cta',
  'provider_policy',
  'dry_run'
];

for (const key of required) {
  const value = request[key];
  if (
    value === undefined ||
    value === null ||
    value === '' ||
    (key === 'provider_policy' && !isPlainObject(value))
  ) {
    errors.push(`Campo obrigatório ausente ou inválido: ${key}`);
  }
}

if (request.schema_version && !/^\d+\.\d+\.\d+$/.test(text(request.schema_version))) {
  errors.push('schema_version deve usar SemVer, por exemplo 1.0.0.');
}

for (const key of ['production_id', 'content_id', 'campaign_id']) {
  const value = text(request[key]);
  if (value && !/^[A-Za-z0-9][A-Za-z0-9._:-]{2,127}$/.test(value)) {
    errors.push(`${key} deve ter 3 a 128 caracteres e usar apenas letras, números, ponto, dois-pontos, hífen ou sublinhado.`);
  }
}

const allowedContentTypes = ['STATIC_SINGLE', 'CAROUSEL', 'SHORT_VIDEO', 'HYBRID'];
if (request.content_type && !allowedContentTypes.includes(request.content_type)) {
  errors.push(`content_type inválido. Permitidos: ${allowedContentTypes.join(', ')}.`);
}

const allowedTiers = ['FAST', 'STANDARD', 'PREMIUM'];
if (request.production_tier && !allowedTiers.includes(request.production_tier)) {
  errors.push(`production_tier inválido. Permitidos: ${allowedTiers.join(', ')}.`);
}

if (typeof request.dry_run !== 'boolean') {
  errors.push('dry_run deve ser booleano: true ou false.');
}

if (text(request.objective).length < 10) {
  errors.push('objective deve explicar o resultado esperado em pelo menos 10 caracteres.');
}
if (text(request.objective).length > 1200) {
  errors.push('objective excede o limite de 1200 caracteres.');
}

if (text(request.cta).length < 2) {
  errors.push('cta deve ter pelo menos 2 caracteres.');
}
if (text(request.cta).length > 160) {
  errors.push('cta excede o limite de 160 caracteres.');
}

const policy = isPlainObject(request.provider_policy)
  ? request.provider_policy
  : {};

const allowedPolicyModes = ['mock', 'allowlist', 'managed', 'live'];
if (policy.mode && !allowedPolicyModes.includes(text(policy.mode).toLowerCase())) {
  errors.push(`provider_policy.mode inválido. Permitidos: ${allowedPolicyModes.join(', ')}.`);
}

if (request.dry_run === true && text(policy.mode).toLowerCase() !== 'mock') {
  warnings.push('dry_run=true com provider_policy.mode diferente de mock; o CCG-00 forçará execução sem efeitos externos.');
}

if (request.dry_run === false) {
  if (text(policy.mode).toLowerCase() === 'mock' || !text(policy.mode)) {
    errors.push('Execução live não pode usar provider_policy.mode=mock ou vazio.');
  }
  if (!Array.isArray(policy.allowed_providers) || !policy.allowed_providers.length) {
    errors.push('Execução live exige provider_policy.allowed_providers com pelo menos um provedor.');
  }
}

for (const numericField of ['max_cost', 'max_jobs', 'max_revisions']) {
  const raw = policy[numericField];
  if (raw !== undefined && raw !== null && raw !== '') {
    const parsed = finiteNumber(raw);
    if (parsed === null || parsed < 0) {
      errors.push(`provider_policy.${numericField} deve ser um número maior ou igual a zero.`);
    }
  }
}

if (!Array.isArray(request.requested_deliverables)) {
  errors.push('requested_deliverables deve ser uma lista quando informado.');
} else {
  const seen = new Set();
  request.requested_deliverables.forEach((deliverable, index) => {
    if (!isPlainObject(deliverable)) {
      errors.push(`requested_deliverables[${index}] deve ser um objeto.`);
      return;
    }

    const deliverableId = text(deliverable.deliverable_id);
    const format = text(deliverable.format);

    if (!deliverableId) {
      errors.push(`requested_deliverables[${index}].deliverable_id é obrigatório.`);
    } else if (seen.has(deliverableId)) {
      errors.push(`deliverable_id duplicado: ${deliverableId}.`);
    } else {
      seen.add(deliverableId);
    }

    if (!format) {
      errors.push(`requested_deliverables[${index}].format é obrigatório.`);
    }
  });
}

for (const listField of [
  'source_assets',
  'brand_assets',
  'references',
  'mandatory_elements',
  'forbidden_elements'
]) {
  if (!Array.isArray(request[listField])) {
    errors.push(`${listField} deve ser uma lista.`);
  }
}

const sensitiveAssets = (request.source_assets || []).filter((asset) => {
  if (!isPlainObject(asset)) return false;
  const subjectType = text(asset.subject_type).toLowerCase();
  return asset.contains_personal_data === true ||
    ['patient', 'client', 'paciente', 'cliente'].includes(subjectType);
});

for (const asset of sensitiveAssets) {
  const consent = isPlainObject(asset.consent) ? asset.consent : {};
  const verified = text(consent.status).toLowerCase() === 'verified';
  if (!verified) {
    const assetLabel = text(asset.asset_id || asset.name || 'sem identificação');
    if (request.dry_run === false) {
      errors.push(`Asset com pessoa identificável sem consentimento verificado: ${assetLabel}.`);
    } else {
      warnings.push(`Dry-run contém asset pessoal sem consentimento verificado: ${assetLabel}.`);
    }
  }
}

if (!(request.brand_assets || []).length) {
  warnings.push('Nenhum brand_asset foi informado; o CCG-40 deverá resolver ou bloquear a produção visual.');
}

if (!(request.requested_deliverables || []).length) {
  warnings.push('Nenhum deliverable foi solicitado; o CCG-20/30 deverá propor formatos antes da produção.');
}

if (!text(request.procedure_or_topic)) {
  warnings.push('procedure_or_topic não foi informado; a fundamentação factual poderá exigir revisão humana.');
}

if (errors.length) {
  throw new Error(
    '[CCG-00/CONTRACT] Requisição rejeitada:\n- ' +
    errors.join('\n- ')
  );
}

return [{
  json: {
    ...data,
    production_request: request,
    ccg_contract: {
      contract_name: 'CCG_PRODUCTION_REQUEST',
      contract_version: '1.0.0',
      validation_mode: 'strict',
      valid: true,
      warnings,
      validated_at: new Date().toISOString()
    }
  },
  binary: item.binary
}];

const item = $input.first();
const data = item.json || {};
const request = data.production_request || data;
const contract = data.ccg_contract || {};

function text(value, fallback = '') {
  if (value === undefined || value === null) return fallback;
  return String(value).trim();
}

function numberInRange(value, fallback, min, max) {
  const parsed = Number(value);
  if (!Number.isFinite(parsed)) return fallback;
  return Math.max(min, Math.min(max, Math.floor(parsed)));
}

function stableStringify(value) {
  if (Array.isArray(value)) {
    return '[' + value.map(stableStringify).join(',') + ']';
  }
  if (value && typeof value === 'object') {
    return '{' + Object.keys(value).sort().map((key) => {
      return JSON.stringify(key) + ':' + stableStringify(value[key]);
    }).join(',') + '}';
  }
  return JSON.stringify(value);
}

function fnv1a32(input, seed = 0x811c9dc5) {
  let hash = seed >>> 0;
  for (let index = 0; index < input.length; index++) {
    hash ^= input.charCodeAt(index);
    hash = Math.imul(hash, 0x01000193) >>> 0;
  }
  return hash.toString(16).padStart(8, '0');
}

function deterministicHash(value) {
  const serialized = stableStringify(value);
  const first = fnv1a32(serialized);
  const second = fnv1a32(
    serialized.split('').reverse().join(''),
    0x9e3779b9
  );
  return first + second;
}

function unique(values) {
  return [...new Set(values.map((value) => text(value)).filter(Boolean))];
}

const now = new Date().toISOString();
const tier = request.production_tier;
const contentType = request.content_type;
const dryRun = request.dry_run === true;
const inputPolicy = request.provider_policy || {};

const tierDefaults = {
  FAST: {
    max_jobs: 4,
    max_revisions: 1,
    factual_depth: 'focused',
    qa_depth: 'standard'
  },
  STANDARD: {
    max_jobs: 12,
    max_revisions: 2,
    factual_depth: 'complete',
    qa_depth: 'complete'
  },
  PREMIUM: {
    max_jobs: 30,
    max_revisions: 4,
    factual_depth: 'extended',
    qa_depth: 'extended'
  }
};

const defaults = tierDefaults[tier];

const policy = {
  mode: dryRun ? 'mock' : text(inputPolicy.mode).toLowerCase(),
  allowed_providers: dryRun
    ? ['mock']
    : unique(inputPolicy.allowed_providers || []),
  max_cost: inputPolicy.max_cost ?? request.budget?.max_cost ?? null,
  max_jobs: numberInRange(
    inputPolicy.max_jobs,
    defaults.max_jobs,
    1,
    120
  ),
  max_revisions: numberInRange(
    inputPolicy.max_revisions,
    defaults.max_revisions,
    0,
    12
  ),
  require_human_approval: inputPolicy.require_human_approval !== false,
  publish_allowed: false
};

const baselineMandatory = [
  'Revisão humana antes de publicação',
  'Usar somente preços, condições e afirmações sustentados pelos insumos',
  'Informar que resultados variam quando houver alegação de resultado'
];

const baselineForbidden = [
  'Garantia de resultado',
  'Diagnóstico clínico automatizado',
  'Preço ou condição comercial não confirmados',
  'Uso de imagem identificável sem consentimento verificável',
  'Publicação automática sem aprovação humana'
];

const mandatoryElements = unique([
  ...(request.mandatory_elements || []),
  ...baselineMandatory
]);

const forbiddenElements = unique([
  ...(request.forbidden_elements || []),
  ...baselineForbidden
]);

const stagePlan = [
  {
    module: 'CCG-10',
    name: 'Factual Foundation',
    required: true,
    reason: 'Validar fatos, ofertas, evidências e riscos.'
  },
  {
    module: 'CCG-20',
    name: 'Content Constitution',
    required: true,
    reason: 'Criar arquitetura da mensagem e copy.'
  },
  {
    module: 'CCG-30',
    name: 'Creative Blueprint',
    required: true,
    reason: 'Definir conceito visual, composição e prompts.'
  },
  {
    module: 'CCG-40',
    name: 'Asset Manifest',
    required: true,
    reason: 'Resolver assets de marca, fontes e geração.'
  },
  {
    module: 'CCG-50',
    name: 'Scene Manifest',
    required: ['CAROUSEL', 'SHORT_VIDEO', 'HYBRID'].includes(contentType),
    reason: 'Planejar páginas, quadros e cenas.'
  },
  {
    module: 'CCG-60',
    name: 'Audio Manifest',
    required: ['SHORT_VIDEO', 'HYBRID'].includes(contentType),
    reason: 'Planejar locução, trilha e efeitos.'
  },
  {
    module: 'CCG-70',
    name: 'Timeline',
    required: ['CAROUSEL', 'SHORT_VIDEO', 'HYBRID'].includes(contentType),
    reason: 'Ordenar páginas ou duração audiovisual.'
  },
  {
    module: 'CCG-80',
    name: 'Production Manifest',
    required: true,
    reason: 'Executar geração e armazenar artefatos.'
  },
  {
    module: 'CCG-90',
    name: 'Content Package',
    required: true,
    reason: 'Executar QA, consolidar arquivos e preparar aprovação.'
  }
];

const hashPayload = {
  schema_version: request.schema_version,
  production_id: request.production_id,
  content_id: request.content_id,
  campaign_id: request.campaign_id,
  content_type: request.content_type,
  production_tier: request.production_tier,
  objective: request.objective,
  cta: request.cta,
  requested_deliverables: request.requested_deliverables,
  source_assets: request.source_assets,
  brand_assets: request.brand_assets,
  offer: request.offer,
  provider_policy: policy,
  dry_run: request.dry_run
};

const requestHash = deterministicHash(hashPayload);
const idempotencyKey = text(
  request.idempotency_key,
  `ccg:${request.campaign_id}:${request.content_id}:${requestHash.slice(0, 12)}`
);

let executionId = '';
let workflowId = '';
try {
  executionId = text($execution.id);
} catch {}
try {
  workflowId = text($workflow.id);
} catch {}

const runId = text(request.run_id, request.production_id);
const warnings = [...(contract.warnings || [])];

if (dryRun) {
  warnings.push('Dry-run ativo: nenhum provedor externo ou publicação deve ser acionado.');
}
if (policy.max_cost === null) {
  warnings.push('Limite financeiro não definido; CCG-80 deve bloquear execução live até receber max_cost.');
}

const intakeManifest = {
  accepted: true,
  decision: warnings.length ? 'ACCEPTED_WITH_WARNINGS' : 'ACCEPTED',
  run_id: runId,
  idempotency_key: idempotencyKey,
  request_hash: requestHash,
  mode: dryRun ? 'DRY_RUN' : 'LIVE',
  content_type: contentType,
  production_tier: tier,
  brand_context: request.brand_context,
  provider_policy: policy,
  compliance: {
    profile: request.brand_context?.compliance_profile || 'SKINCOS_AESTHETICS_BR_V1',
    mandatory_elements: mandatoryElements,
    forbidden_elements: forbiddenElements,
    human_approval_required: true,
    publish_allowed: false
  },
  limits: {
    max_jobs: policy.max_jobs,
    max_revisions: policy.max_revisions,
    max_cost: policy.max_cost,
    factual_depth: defaults.factual_depth,
    qa_depth: defaults.qa_depth
  },
  stage_plan: stagePlan,
  next_module: 'CCG-10',
  warnings,
  accepted_at: now
};

const priorOutputs = data.module_outputs && typeof data.module_outputs === 'object'
  ? data.module_outputs
  : {};

const priorTrace = Array.isArray(data.module_trace)
  ? data.module_trace
  : [];

const moduleOutput = {
  status: 'DONE',
  output_type: 'INTAKE_MANIFEST',
  started_at: data.ccg_input?.normalized_at || request.received_at || now,
  finished_at: now,
  intake_manifest: intakeManifest
};

const ledgerEvent = {
  event_name: 'ccg.production.accepted',
  event_version: '1.0.0',
  event_id: `${runId}:CCG-00:accepted:${requestHash.slice(0, 12)}`,
  occurred_at: now,
  idempotency_key: idempotencyKey,
  payload: {
    run_id: runId,
    production_id: request.production_id,
    campaign_id: request.campaign_id,
    content_id: request.content_id,
    mode: intakeManifest.mode,
    decision: intakeManifest.decision,
    next_module: intakeManifest.next_module
  }
};

return [{
  json: {
    ...data,
    ...request,
    production_request: {
      ...request,
      provider_policy: policy,
      mandatory_elements: mandatoryElements,
      forbidden_elements: forbiddenElements,
      idempotency_key: idempotencyKey,
      run_id: runId
    },
    ccg_context: {
      workflow_family: 'Campaign Creative Generator',
      builder_version: '3.0.0',
      contract_version: contract.contract_version || '1.0.0',
      run_id: runId,
      execution_id: executionId,
      workflow_id: workflowId,
      request_hash: requestHash,
      idempotency_key: idempotencyKey,
      mode: intakeManifest.mode,
      received_at: request.received_at,
      accepted_at: now
    },
    module_outputs: {
      ...priorOutputs,
      CCG_00: moduleOutput
    },
    module_trace: [
      ...priorTrace,
      {
        module: 'CCG-00',
        status: 'DONE',
        output_type: 'INTAKE_MANIFEST',
        finished_at: now
      }
    ],
    ledger_events: [
      ...(Array.isArray(data.ledger_events) ? data.ledger_events : []),
      ledgerEvent
    ],
    ccg_module: 'CCG-00',
    module_status: 'DONE',
    module_output: 'intake_manifest',
    next_module: 'CCG-10',
    status: 'IN_PROGRESS'
  },
  binary: item.binary
}];

const item = $input.first();
const data = item.json || {};
const output = data.module_outputs?.CCG_00;

if (!output || output.status !== 'DONE' || !output.intake_manifest?.accepted) {
  throw new Error('[CCG-00/OUTPUT] O módulo não produziu um intake_manifest aceito.');
}

return [{
  json: {
    ...data,
    module_trace: [
      ...(data.module_trace || []),
      ...((data.module_trace || []).some((entry) => entry && entry.module === 'CCG-00') ? [] : [{
        module: 'CCG-00',
        status: output?.status || 'DONE',
        run_id: data.ccg_context?.run_id,
        idempotency_key: data.ccg_context?.idempotency_key
      }])
    ],
    ledger_events: [
      ...(data.ledger_events || []),
      ...((data.ledger_events || []).some((entry) => entry && (entry.module === 'CCG-00' || entry.event_id === data.ccg_context?.run_id + ':CCG-00')) ? [] : [{
        event_name: 'ccg.module.completed',
        event_id: (data.ccg_context?.run_id || 'unknown') + ':CCG-00',
        module: 'CCG-00',
        status: output?.status || 'DONE',
        idempotency_key: data.ccg_context?.idempotency_key
      }])
    ],
    output_type: 'CCG_MODULE_RESULT',
    module_result: {
      module: 'CCG-00',
      status: 'DONE',
      output_type: 'INTAKE_MANIFEST',
      next_module: data.next_module || 'CCG-10',
      run_id: data.ccg_context?.run_id,
      idempotency_key: data.ccg_context?.idempotency_key,
      warnings: output.intake_manifest.warnings || []
    },
    posting_payload: {
      publish_requested: false,
      publish_allowed: false
    },
    error_handling: 'throw-and-native-workflow-execution',
    external_error_workflow: false
  },
  binary: item.binary
}];

const item = $input.first();
const data = item.json || {};
const request = data.production_request;
const intake = data.module_outputs?.CCG_00?.intake_manifest;

function text(value) {
  if (value === undefined || value === null) return '';
  return String(value).trim();
}

function arrayValue(value) {
  return Array.isArray(value) ? value : [];
}

const errors = [];
const warnings = [];

if (!request || typeof request !== 'object' || Array.isArray(request)) {
  errors.push('production_request ausente ou inválido. Execute o CCG-00 antes do CCG-10.');
}

if (data.module_outputs?.CCG_00?.status !== 'DONE') {
  errors.push('CCG-00 não está concluído.');
}

if (!intake?.accepted) {
  errors.push('CCG-00 não aceitou a requisição.');
}

if (text(data.next_module) && text(data.next_module) !== 'CCG-10') {
  errors.push(`Roteamento inválido: esperado CCG-10, recebido ${text(data.next_module)}.`);
}

if (!text(data.ccg_context?.run_id)) errors.push('ccg_context.run_id ausente.');
if (!text(data.ccg_context?.idempotency_key)) errors.push('ccg_context.idempotency_key ausente.');
if (!text(data.ccg_context?.request_hash)) warnings.push('ccg_context.request_hash ausente; rastreabilidade reduzida.');

const mode = text(data.ccg_context?.mode).toUpperCase();
if (!['DRY_RUN', 'LIVE'].includes(mode)) {
  errors.push('ccg_context.mode deve ser DRY_RUN ou LIVE.');
}

const allowedProviders = arrayValue(request?.provider_policy?.allowed_providers)
  .map((provider) => text(provider).toLowerCase());

if (mode === 'LIVE' && !allowedProviders.includes('openai')) {
  errors.push('CCG-10 live exige openai em provider_policy.allowed_providers.');
}

if (!arrayValue(request?.source_assets).length && !text(request?.procedure_or_topic) && !text(request?.offer?.title)) {
  errors.push('Nenhuma fonte, tema ou oferta foi fornecida para construir a base factual.');
}

if (!arrayValue(request?.source_assets).length) {
  warnings.push('Nenhum source_asset foi fornecido; fatos do pedido serão tratados como fornecidos, não verificados.');
}

if (errors.length) {
  throw new Error('[CCG-10/PREFLIGHT] Requisição rejeitada:\n- ' + errors.join('\n- '));
}

return [{
  json: {
    ...data,
    ccg_10_preflight: {
      valid: true,
      mode,
      allowed_providers: allowedProviders,
      warnings,
      checked_at: new Date().toISOString()
    }
  },
  binary: item.binary
}];

const item = $input.first();
const data = item.json || {};
const request = data.production_request || {};
const binary = item.binary || {};

function text(value, fallback = '') {
  if (value === undefined || value === null) return fallback;
  return String(value).trim();
}

function list(value) {
  return Array.isArray(value) ? value : [];
}

function objectValue(value) {
  return value && typeof value === 'object' && !Array.isArray(value) ? value : {};
}

function clamp(value, min, max, fallback) {
  const parsed = Number(value);
  if (!Number.isFinite(parsed)) return fallback;
  return Math.max(min, Math.min(max, parsed));
}

function slug(value, fallback = 'source') {
  const normalized = text(value)
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-zA-Z0-9]+/g, '-')
    .replace(/^-|-$/g, '')
    .toLowerCase();
  return normalized || fallback;
}

function redact(value) {
  return text(value)
    .replace(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi, '[EMAIL_REDACTED]')
    .replace(/\b\d{3}\.?\d{3}\.?\d{3}-?\d{2}\b/g, '[CPF_REDACTED]')
    .replace(/(?:\+?55\s*)?(?:\(?\d{2}\)?\s*)?(?:9\s*)?\d{4}[-\s]?\d{4}\b/g, '[PHONE_REDACTED]');
}

function authority(value, approved) {
  const normalized = text(value).toLowerCase();
  const allowed = ['primary', 'approved_internal', 'provided_material', 'secondary', 'unknown'];
  if (allowed.includes(normalized)) return normalized;
  if (approved === true) return 'approved_internal';
  return 'provided_material';
}

function sourceText(source) {
  const parts = [
    source.text,
    source.text_excerpt,
    source.extracted_text,
    source.description,
    source.evidence,
    source.notes
  ].map(redact).filter(Boolean);

  for (const fact of list(source.facts)) {
    const obj = objectValue(fact);
    parts.push(redact(obj.statement || obj.fact || obj.text));
    parts.push(redact(obj.evidence_quote));
  }

  for (const offer of list(source.offers)) {
    const obj = objectValue(offer);
    parts.push(redact([
      obj.title,
      obj.price,
      obj.payment_terms,
      obj.conditions,
      obj.validity,
      obj.evidence_quote
    ].filter(Boolean).join(' | ')));
  }

  for (const claim of list(source.claims)) {
    const obj = objectValue(claim);
    parts.push(redact(obj.statement || obj.claim));
    parts.push(redact(obj.evidence_quote));
  }

  return parts.filter(Boolean).join('\n');
}

function extractPdfText() {
  return { text: '', status: 'DEFERRED_UNSUPPORTED_RUNTIME' };
}

const tierLimits = {
  FAST: 12000,
  STANDARD: 30000,
  PREMIUM: 60000
};
const maxChars = clamp(
  request.factual_limits?.max_source_chars,
  4000,
  100000,
  tierLimits[request.production_tier] || 12000
);

const sourceRecords = [];
const sourceAssets = list(request.source_assets);

for (let index = 0; index < sourceAssets.length; index++) {
  const source = objectValue(sourceAssets[index]);
  const sourceId = text(
    source.source_id || source.asset_id || source.id,
    `source-${index + 1}`
  );
  const excerpt = sourceText(source).slice(0, maxChars);
  sourceRecords.push({
    source_id: sourceId,
    source_type: text(source.type || source.kind, 'PROVIDED_ASSET').toUpperCase(),
    title: text(source.title || source.name, sourceId),
    locator: text(source.url || source.webViewLink || source.path),
    authority_level: authority(source.authority_level, source.approved),
    approved: source.approved === true,
    usable: Boolean(excerpt || source.url || source.webViewLink),
    content_sha256: text(source.sha256 || source.content_sha256),
    text_excerpt: excerpt,
    structured: {
      facts: list(source.facts),
      offers: list(source.offers),
      claims: list(source.claims)
    }
  });
}

let binaryIndex = 0;
for (const [binaryKey, metaValue] of Object.entries(binary || {})) {
  const meta = metaValue && typeof metaValue === 'object' ? metaValue : {};
  const fileName = text(meta.fileName || meta.file_name || binaryKey);
  const mimeType = text(meta.mimeType || meta.mime_type || meta.contentType).toLowerCase();
  let buffer = null;
  try {
    if (this.helpers && typeof this.helpers.getBinaryDataBuffer === 'function') {
      buffer = await this.helpers.getBinaryDataBuffer(0, binaryKey);
    }
  } catch (error) {
    buffer = null;
  }
  const suppliedChecksum = text(meta.sha256 || meta.content_sha256 || (typeof meta.checksum === 'string' ? meta.checksum : meta.checksum && meta.checksum.value));
  const isPdf = mimeType === 'application/pdf' || /\.pdf$/i.test(fileName);
  const isTextBinary = mimeType.startsWith('text/') || /\.(txt|md|csv|json)$/i.test(fileName);
  const isImage = mimeType.startsWith('image/');
  let excerpt = '';
  let textExtractionStatus = 'NOT_APPLICABLE';
  if (isPdf) {
    textExtractionStatus = 'DEFERRED_UNSUPPORTED_RUNTIME';
  } else if (isTextBinary && buffer) {
    excerpt = redact(buffer.toString('utf8')).slice(0, 12000);
    textExtractionStatus = 'EXTRACTED_FROM_TEXT_BINARY';
  } else if (!isImage) {
    textExtractionStatus = 'UNSUPPORTED_BINARY';
  }
  sourceRecords.push({
    source_id: 'production-request:binary:' + binaryIndex,
    source_type: isImage ? 'IMAGE' : isPdf ? 'PDF' : 'BINARY',
    file_name: fileName,
    mime_type: mimeType,
    usable: Boolean(excerpt || isImage),
    excerpt,
    content_sha256: suppliedChecksum,
    text_extraction_status: textExtractionStatus,
    metadata: {
      checksum_source: suppliedChecksum ? 'provided_metadata' : 'missing',
      size_bytes: Number(meta.fileSize || meta.file_size || 0) || null,
    },
  });
  binaryIndex += 1;
}

const requestSourceId = 'production-request';
const requestEvidence = [
  `Objetivo informado: ${text(request.objective)}`,
  `CTA informado: ${text(request.cta)}`,
  `Tema informado: ${text(request.procedure_or_topic)}`,
  request.offer && Object.keys(request.offer).length
    ? `Oferta informada: ${JSON.stringify(request.offer)}`
    : ''
].filter(Boolean).join('\n');

sourceRecords.unshift({
  source_id: requestSourceId,
  source_type: 'PRODUCTION_REQUEST',
  title: 'Solicitação de produção',
  locator: 'production_request',
  authority_level: 'provided_material',
  approved: false,
  usable: true,
  content_sha256: '',
  text_excerpt: redact(requestEvidence).slice(0, maxChars),
  structured: {
    facts: [],
    offers: [],
    claims: []
  }
});

let consumed = 0;
const combinedBlocks = [];
for (const source of sourceRecords) {
  if (!source.text_excerpt) continue;
  const remaining = maxChars - consumed;
  if (remaining <= 0) break;
  const block = `[SOURCE ${source.source_id} | ${source.authority_level}]\n${source.text_excerpt}`.slice(0, remaining);
  combinedBlocks.push(block);
  consumed += block.length;
}

const usableSources = sourceRecords.filter((source) => source.usable);
const approvedSources = sourceRecords.filter((source) =>
  ['primary', 'approved_internal'].includes(source.authority_level)
);

return [{
  json: {
    ...data,
    evidence_dossier: {
      dossier_version: '1.0.0',
      evidence_policy: 'CLOSED_WORLD_ONLY',
      max_source_chars: maxChars,
      sources: sourceRecords,
      combined_text: combinedBlocks.join('\n\n'),
      summary: {
        total_sources: sourceRecords.length,
        usable_sources: usableSources.length,
        approved_sources: approvedSources.length,
        binary_sources: binaryIndex,
        image_sources: sourceRecords.filter((source) => source.source_type === 'IMAGE').length,
        pdf_sources: sourceRecords.filter((source) => source.source_type === 'PDF').length,
        extracted_characters: consumed,
        personal_data_redaction_applied: true
      },
      rules: [
        'Use somente o conteúdo deste dossiê como evidência.',
        'Não complete lacunas com conhecimento geral.',
        'Preço, condição, validade, indicação, eficácia e segurança exigem evidência explícita.',
        'Quando houver conflito, preserve o conflito e solicite revisão humana.',
        'Imagens anexadas podem ser interpretadas, mas texto ilegível deve virar dúvida, nunca suposição.'
      ],
      prepared_at: new Date().toISOString()
    },
    ccg_module: 'CCG-10',
    module_status: 'RUNNING',
    module_output: 'evidence_dossier'
  },
  binary
}];

const data = $input.first().json || {};
const request = data.production_request || {};
const dossier = data.evidence_dossier || {};

function text(value, fallback = '') {
  if (value === undefined || value === null) return fallback;
  return String(value).trim();
}

function list(value) {
  return Array.isArray(value) ? value : [];
}

function objectValue(value) {
  return value && typeof value === 'object' && !Array.isArray(value) ? value : {};
}

function unique(values) {
  return [...new Set(values.map((value) => text(value)).filter(Boolean))];
}

const sourceRegistry = list(dossier.sources).map((source) => ({
  source_id: text(source.source_id),
  source_type: text(source.source_type),
  title: text(source.title),
  locator: text(source.locator),
  authority_level: text(source.authority_level, 'unknown'),
  usable: source.usable === true
}));

const facts = [];
const offers = [];
const claims = [];
let factIndex = 0;
let offerIndex = 0;
let claimIndex = 0;

for (const source of list(dossier.sources)) {
  const structured = objectValue(source.structured);
  for (const rawFact of list(structured.facts)) {
    const fact = objectValue(rawFact);
    const statement = text(fact.statement || fact.fact || fact.text);
    if (!statement) continue;
    factIndex++;
    facts.push({
      fact_id: text(fact.fact_id, `fact-${factIndex}`),
      statement,
      category: text(fact.category, 'other'),
      source_ids: unique([...(list(fact.source_ids)), source.source_id]),
      evidence_quote: text(fact.evidence_quote),
      confidence: Number.isFinite(Number(fact.confidence)) ? Number(fact.confidence) : 0.7,
      status: 'supported',
      expires_at: text(fact.expires_at)
    });
  }

  for (const rawOffer of list(structured.offers)) {
    const offer = objectValue(rawOffer);
    const title = text(offer.title);
    if (!title) continue;
    offerIndex++;
    offers.push({
      offer_id: text(offer.offer_id, `offer-${offerIndex}`),
      title,
      price: text(offer.price),
      payment_terms: text(offer.payment_terms),
      conditions: text(offer.conditions),
      validity: text(offer.validity),
      source_ids: unique([...(list(offer.source_ids)), source.source_id]),
      evidence_quote: text(offer.evidence_quote || offer.evidence),
      confidence: Number.isFinite(Number(offer.confidence)) ? Number(offer.confidence) : 0.7,
      status: 'needs_review'
    });
  }

  for (const rawClaim of list(structured.claims)) {
    const claim = objectValue(rawClaim);
    const statement = text(claim.statement || claim.claim);
    if (!statement) continue;
    claimIndex++;
    claims.push({
      claim_id: text(claim.claim_id, `claim-${claimIndex}`),
      statement,
      claim_type: text(claim.claim_type, 'other'),
      source_ids: unique([...(list(claim.source_ids)), source.source_id]),
      evidence_quote: text(claim.evidence_quote),
      confidence: Number.isFinite(Number(claim.confidence)) ? Number(claim.confidence) : 0.5,
      status: 'needs_review',
      reason: 'Dry-run: alegação ainda não passou pela auditoria live.'
    });
  }
}

if (text(request.procedure_or_topic)) {
  factIndex++;
  facts.push({
    fact_id: `fact-${factIndex}`,
    statement: `O tema solicitado é ${text(request.procedure_or_topic)}.`,
    category: 'campaign',
    source_ids: ['production-request'],
    evidence_quote: `Tema informado: ${text(request.procedure_or_topic)}`,
    confidence: 1,
    status: 'provided_unverified',
    expires_at: ''
  });
}

const requestOffer = objectValue(request.offer);
if (text(requestOffer.title) && !offers.some((offer) => offer.offer_id === text(requestOffer.offer_id))) {
  offerIndex++;
  offers.push({
    offer_id: text(requestOffer.offer_id, `offer-${offerIndex}`),
    title: text(requestOffer.title),
    price: text(requestOffer.price),
    payment_terms: text(requestOffer.payment_terms),
    conditions: text(requestOffer.conditions),
    validity: text(requestOffer.validity),
    source_ids: unique([...(list(requestOffer.source_ids)), 'production-request']),
    evidence_quote: text(requestOffer.evidence),
    confidence: text(requestOffer.evidence) ? 0.7 : 0.4,
    status: 'needs_review'
  });
}

const openQuestions = [];
if (!sourceRegistry.some((source) => ['primary', 'approved_internal'].includes(source.authority_level))) {
  openQuestions.push({
    question_id: 'question-approved-source',
    question: 'Qual material aprovado confirma os preços, condições e alegações que serão publicados?',
    blocking: false,
    reason: 'Não há fonte primária ou interna aprovada no dossiê.'
  });
}

if (!facts.length && !offers.length && !claims.length) {
  openQuestions.push({
    question_id: 'question-no-facts',
    question: 'Quais fatos objetivos devem sustentar a campanha?',
    blocking: true,
    reason: 'Nenhum fato estruturado foi encontrado no dry-run.'
  });
}

const requiredDisclaimers = [];
if (text(request.procedure_or_topic)) {
  requiredDisclaimers.push('Avaliação individual necessária; resultados podem variar.');
}

return [{
  json: {
    ...data,
    analysis_candidate: {
      factual_foundation: {
        topic_summary: text(request.procedure_or_topic || request.objective),
        source_registry: sourceRegistry,
        facts,
        offers,
        claims,
        required_disclaimers: requiredDisclaimers,
        forbidden_claims: unique([
          ...(list(request.forbidden_elements)),
          'Garantia de resultado',
          'Procedimento sem risco',
          'Resultado definitivo sem evidência aprovada'
        ]),
        open_questions: openQuestions,
        risk_flags: openQuestions.some((question) => question.blocking)
          ? [{
              code: 'INSUFFICIENT_EVIDENCE',
              severity: 'high',
              description: 'Nenhuma base factual estruturada foi encontrada.',
              affected_ids: []
            }]
          : []
      }
    },
    analysis_provider: 'deterministic-dry-run',
    analysis_completed_at: new Date().toISOString()
  }
}];

