parameters.jsCode:
const incomingItem = $input.first();
const incoming = incomingItem.json || {};
const baseItem = $('CCG-10 Prepare Evidence Dossier').first();
const base = baseItem.json || {};
const request = base.production_request || {};
const dossier = base.evidence_dossier || {};

function text(value, fallback = '') {
  if (value === undefined || value === null) return fallback;
  return String(value).trim();
}

function list(value) {
  return Array.isArray(value) ? value : [];
}

function objectValue(value) {
  return value && typeof value === 'object' && !Array.isArray(value) ? value : {};
}

function unique(values) {
  return [...new Set(values.map((value) => text(value)).filter(Boolean))];
}

function confidence(value, fallback = 0) {
  const parsed = Number(value);
  if (!Number.isFinite(parsed)) return fallback;
  return Math.max(0, Math.min(1, parsed));
}

function dedupeRecords(items, idField, prefix, statusPriority) {
  const merged = new Map();
  list(items).forEach((raw, index) => {
    const current = objectValue(raw);
    const id = text(current[idField], `${prefix}-${index + 1}`);
    const previous = merged.get(id);
    if (!previous) {
      merged.set(id, { ...current, [idField]: id });
      return;
    }

    const previousQuote = text(previous.evidence_quote || previous.evidence);
    const currentQuote = text(current.evidence_quote || current.evidence);
    const previousStatus = text(previous.status).toLowerCase();
    const currentStatus = text(current.status).toLowerCase();
    const selectedStatus = (statusPriority[currentStatus] || 0) > (statusPriority[previousStatus] || 0)
      ? currentStatus
      : previousStatus;

    merged.set(id, {
      ...previous,
      ...current,
      [idField]: id,
      source_ids: unique([...list(previous.source_ids), ...list(current.source_ids)]),
      evidence_quote: currentQuote.length > previousQuote.length ? currentQuote : previousQuote,
      confidence: Math.max(confidence(previous.confidence, 0), confidence(current.confidence, 0)),
      status: selectedStatus
    });
  });
  return [...merged.values()];
}

function parseJson(value) {
  try {
    return JSON.parse(value);
  } catch {
    return null;
  }
}

function unwrap(value) {
  if (value?.analysis_candidate) return value.analysis_candidate;
  if (value?.output && typeof value.output === 'object') return value.output;
  if (typeof value?.output === 'string') return parseJson(value.output) || {};
  if (typeof value?.text === 'string') return parseJson(value.text) || {};
  return value || {};
}

function slug(value, fallback) {
  const result = text(value)
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-zA-Z0-9]+/g, '-')
    .replace(/^-|-$/g, '')
    .toLowerCase();
  return result || fallback;
}

const candidate = unwrap(incoming);
const rawFoundation = objectValue(candidate.factual_foundation || candidate);
const dossierSources = list(dossier.sources);
const sourceMap = new Map(dossierSources.map((source) => [text(source.source_id), source]));
const validSourceIds = new Set(sourceMap.keys());

const sourceRegistry = dossierSources.map((source) => ({
  source_id: text(source.source_id),
  source_type: text(source.source_type),
  title: text(source.title),
  locator: text(source.locator),
  authority_level: text(source.authority_level, 'unknown'),
  usable: source.usable === true
}));

const reviewReasons = [];
const riskFlags = list(rawFoundation.risk_flags).map((flag, index) => ({
  code: text(flag.code, `RISK_${index + 1}`),
  severity: ['low', 'medium', 'high', 'critical'].includes(text(flag.severity).toLowerCase())
    ? text(flag.severity).toLowerCase()
    : 'medium',
  description: text(flag.description),
  affected_ids: unique(list(flag.affected_ids))
}));

const facts = dedupeRecords(rawFoundation.facts, 'fact_id', 'fact', { rejected: 4, conflicting: 3, provided_unverified: 2, supported: 1, verified: 1 }).map((raw, index) => {
  const fact = objectValue(raw);
  const factId = text(fact.fact_id, `fact-${index + 1}`);
  const sourceIds = unique(list(fact.source_ids)).filter((id) => validSourceIds.has(id));
  const quote = text(fact.evidence_quote).slice(0, 500);
  const score = confidence(fact.confidence, 0);
  const authorities = sourceIds.map((id) => text(sourceMap.get(id)?.authority_level));
  const hasApprovedSource = authorities.some((level) => ['primary', 'approved_internal'].includes(level));
  let status = text(fact.status).toLowerCase();

  if (status === 'conflicting' || status === 'rejected') {
    // Preserve explicit conflict/rejection.
  } else if (hasApprovedSource && quote && score >= 0.85) {
    status = 'verified';
  } else if (sourceIds.length && quote && score >= 0.65) {
