    reviewReasons.push(`Fato sem evidência suficiente: ${factId}`);
  }

  return {
    fact_id: factId,
    statement: text(fact.statement),
    category: text(fact.category, 'other'),
    source_ids: sourceIds,
    evidence_quote: quote,
    confidence: score,
    status,
