const deliverables = requested.slice(0, maxJobs).map((rawValue, index) => {
  const raw = objectValue(rawValue);
  const contentMode = normalizedMode(raw, text(request.content_type), index);
  const format = text(raw.format, contentMode === 'SHORT_VIDEO' ? '9:16' : '4:5');
  const deliverableId = text(raw.deliverable_id, `${text(request.content_id, 'content')}-${index + 1}`);

  return {
    deliverable_id: deliverableId,
    content_mode: contentMode,
    format,
    usage: text(raw.usage, 'ORGANIC').toUpperCase(),
    purpose: text(raw.purpose, request.objective),
    slide_count: contentMode === 'CAROUSEL'
      ? clampInt(raw.pages || raw.slides, Math.min(5, profile.max_slide_count), 3, profile.max_slide_count)
      : 0,
    scene_count: contentMode === 'SHORT_VIDEO'
      ? clampInt(raw.scenes, Math.min(5, profile.max_scene_count), 3, profile.max_scene_count)
      : 0,
    duration_seconds: contentMode === 'SHORT_VIDEO'
      ? clampInt(raw.duration_seconds || raw.duration, profile.default_video_seconds, 6, 90)
      : 0,
    copy_limits: {
      headline_chars: profile.headline_chars,
      subheadline_chars: profile.subheadline_chars,
      body_chars: profile.body_chars,
      caption_chars: profile.caption_chars
    }
  };
});

const requiredDisclaimers = unique(list(foundation.required_disclaimers));
const forbiddenCopy = unique([
  ...list(foundation.forbidden_claims),
  ...list(request.forbidden_elements),
  'Garantia de resultado',
  'Resultado certo',
  'Procedimento sem risco',
  'Cura',
  'Preço ou condição não confirmados',
  'Antes e depois sem autorização e revisão'
]);

const allowedNumericTokens = unique(
  approvedReferences.flatMap((reference) => extractNumericTokens([
    reference.text,
    reference.evidence_quote
  ].filter(Boolean).join(' ')))
);

const brief = {
  brief_version: '1.0.0',
  evidence_policy: 'ALLOWLIST_ONLY',
  run_id: text(data.ccg_context?.run_id),
  campaign_id: text(request.campaign_id),
  content_id: text(request.content_id),
  content_type: text(request.content_type),
  production_tier: tier,
  objective: text(request.objective),
  funnel_stage: text(request.funnel_stage, 'consideration'),
  audience: objectValue(request.audience),
  procedure_or_topic: text(request.procedure_or_topic),
  brand: {
    brand_name: text(request.brand_context?.brand_name, 'Espaço Facial'),
    locale: text(request.brand_context?.locale, 'pt-BR'),
    voice: text(
      request.brand_context?.voice ||
      request.organizer_context?.tone,
      'premium, claro, humano, acolhedor e seguro'
    )
  },
  primary_cta: text(request.cta),
  approved_references: approvedReferences,
  allowed_reference_ids: approvedReferences.map((reference) => reference.ref_id),
  allowed_numeric_tokens: allowedNumericTokens,
  blocked_fragments: blockedFragments,
  required_disclaimers: requiredDisclaimers,
  mandatory_elements: unique(list(request.mandatory_elements)),
  forbidden_copy: forbiddenCopy,
  deliverables,
  creative_constraints: {
    variant_count: profile.variant_count,
    use_only_allowed_reference_ids: true,
    never_invent_price_or_condition: true,
    never_create_clinical_claim_without_reference: true,
    primary_cta_is_locked: true,
    publication_requires_human_approval: true,
    publish_allowed: false
  },
  upstream_status: {
    factual_status: text(foundation.status),
    routing_decision: text(foundation.routing_decision),
    review_reasons: unique(list(foundation.review?.reasons))
  },
  prepared_at: new Date().toISOString()
};

return [{
  json: {
    ...data,
    copy_brief: brief,
    ccg20_preparation: {
      approved_reference_count: approvedReferences.length,
      allowed_fact_count: allowedFacts.length,
      allowed_offer_count: allowedOffers.length,
      allowed_claim_count: allowedClaims.length,
      blocked_fragment_count: blockedFragments.length,
      deliverable_count: deliverables.length,
      prepared_at: brief.prepared_at
    }
  },
  binary: item.binary
}];

const data = $input.first().json || {};
const brief = data.copy_brief || {};

function text(value, fallback = '') {
  if (value === undefined || value === null) return fallback;
  return String(value).trim();
}

function list(value) {
  return Array.isArray(value) ? value : [];
}

function truncate(value, max) {
  const source = text(value);
  if (!Number.isFinite(Number(max)) || source.length <= Number(max)) return source;
  return source.slice(0, Math.max(0, Number(max) - 1)).trimEnd() + '…';
}

const references = list(brief.approved_references);
const offer = references.find((reference) => reference.kind === 'offer');
const claim = references.find((reference) => reference.kind === 'claim');
const fact = references.find((reference) => reference.kind === 'fact');

const topic = text(
  brief.procedure_or_topic,
  text(offer?.title, text(brief.brand?.brand_name, 'Campanha'))
);

const centralProposition = text(
  claim?.text,
  offer
    ? `Conheça ${text(offer.title)}.`
    : `Conheça ${topic}.`
);

function baseEvidenceRefs() {
  return [
    text(offer?.ref_id),
    text(claim?.ref_id),
    text(fact?.ref_id)
  ].filter(Boolean);
}

function offerLine() {
  if (!offer) return '';
  return [
    text(offer.price),
    text(offer.payment_terms),
    text(offer.conditions),
    text(offer.validity)
  ].filter(Boolean).join(' · ');
}

function disclaimer() {
  return list(brief.required_disclaimers).join(' ');
}

function staticDeliverable(spec) {
  const limits = spec.copy_limits || {};
  const headline = truncate(text(offer?.title, topic), limits.headline_chars);
  const subheadline = truncate(offerLine(), limits.subheadline_chars);
  const body = truncate(
    claim
      ? text(claim.text)
      : `Informações construídas somente a partir do briefing aprovado da campanha.`,
    limits.body_chars
  );

  return {
    deliverable_id: spec.deliverable_id,
    format: spec.format,
    content_mode: spec.content_mode,
    purpose: spec.purpose,
    copy: {
      headline,
      subheadline,
      body,
      cta: brief.primary_cta,
      disclaimer: disclaimer()
    },
    slides: [],
    scenes: [],
    caption: {
      hook: headline,
      body: [body, subheadline].filter(Boolean).join('\n\n'),
      cta: brief.primary_cta,
      disclaimer: disclaimer(),
      hashtags: []
    },
    evidence_refs: baseEvidenceRefs(),
    review_notes: ['Dry-run determinístico: revisar acabamento editorial antes da produção.']
  };
}

function carouselDeliverable(spec) {
  const count = Math.max(3, Number(spec.slide_count || 5));
  const slides = [];
  slides.push({
    sequence: 1,
    role: 'hook',
    headline: text(offer?.title, topic),
    body: '',
    cta: '',
    evidence_refs: [text(offer?.ref_id, text(fact?.ref_id))].filter(Boolean)
  });

  if (claim) {
    slides.push({
      sequence: slides.length + 1,
      role: 'value',
      headline: 'O que está confirmado',
      body: text(claim.text),
      cta: '',
      evidence_refs: [claim.ref_id]
    });
  } else if (fact) {
    slides.push({
      sequence: slides.length + 1,
      role: 'context',
      headline: 'Informação da campanha',
      body: text(fact.text),
      cta: '',
      evidence_refs: [fact.ref_id]
    });
  }

  if (offer) {
    slides.push({
      sequence: slides.length + 1,
      role: 'offer',
      headline: 'Condição da campanha',
      body: offerLine(),
      cta: '',
      evidence_refs: [offer.ref_id]
    });
  }

  while (slides.length < count - 1) {
    slides.push({
      sequence: slides.length + 1,
      role: 'support',
      headline: 'Planejamento individual',
      body: disclaimer() || 'A avaliação orienta a indicação adequada para cada pessoa.',
      cta: '',
      evidence_refs: []
    });
  }

  slides.push({
    sequence: slides.length + 1,
    role: 'cta',
    headline: brief.primary_cta,
    body: disclaimer(),
    cta: brief.primary_cta,
    evidence_refs: [text(fact?.ref_id)].filter(Boolean)
  });

  return {
    deliverable_id: spec.deliverable_id,
    format: spec.format,
    content_mode: spec.content_mode,
    purpose: spec.purpose,
    copy: {
      headline: text(offer?.title, topic),
      subheadline: offerLine(),
      body: centralProposition,
      cta: brief.primary_cta,
      disclaimer: disclaimer()
    },
    slides: slides.slice(0, count),
    scenes: [],
    caption: {
      hook: text(offer?.title, topic),
      body: [centralProposition, offerLine()].filter(Boolean).join('\n\n'),
      cta: brief.primary_cta,
      disclaimer: disclaimer(),
      hashtags: []
    },
    evidence_refs: baseEvidenceRefs(),
    review_notes: ['Dry-run determinístico: validar ritmo e hierarquia dos cards.']
  };
}

function videoDeliverable(spec) {
  const count = Math.max(3, Number(spec.scene_count || 4));
  const total = Math.max(6, Number(spec.duration_seconds || 20));
  const duration = Math.max(2, Math.floor(total / count));
  const sceneBlueprint = [
    {
      role: 'hook',
      voiceover: text(offer?.title, topic),
      on_screen_text: text(offer?.title, topic),
      evidence_refs: [text(offer?.ref_id, text(fact?.ref_id))].filter(Boolean)
    },
    {
      role: 'value',
      voiceover: centralProposition,
      on_screen_text: centralProposition,
      evidence_refs: [text(claim?.ref_id, text(fact?.ref_id))].filter(Boolean)
    },
    {
      role: 'offer',
      voiceover: offerLine(),
      on_screen_text: offerLine(),
      evidence_refs: [text(offer?.ref_id)].filter(Boolean)
    },
    {
      role: 'cta',
      voiceover: brief.primary_cta,
      on_screen_text: brief.primary_cta,
      evidence_refs: [text(fact?.ref_id)].filter(Boolean)
    }
  ].filter((scene) => scene.voiceover || scene.on_screen_text);

  while (sceneBlueprint.length < count) {
    sceneBlueprint.splice(Math.max(1, sceneBlueprint.length - 1), 0, {
      role: 'support',
      voiceover: disclaimer() || `Conheça ${topic}.`,
      on_screen_text: disclaimer() || `Conheça ${topic}.`,
      evidence_refs: []
    });
  }

  const scenes = sceneBlueprint.slice(0, count).map((scene, index) => ({
    sequence: index + 1,
    role: scene.role,
    duration_seconds: index === count - 1
      ? Math.max(2, total - duration * (count - 1))
      : duration,
    voiceover: scene.voiceover,
    on_screen_text: scene.on_screen_text,
    evidence_refs: scene.evidence_refs
  }));

  return {
    deliverable_id: spec.deliverable_id,
    format: spec.format,
    content_mode: spec.content_mode,
    purpose: spec.purpose,
    copy: {
      headline: text(offer?.title, topic),
      subheadline: offerLine(),
      body: centralProposition,
      cta: brief.primary_cta,
      disclaimer: disclaimer()
    },
    slides: [],
    scenes,
    caption: {
      hook: text(offer?.title, topic),
      body: [centralProposition, offerLine()].filter(Boolean).join('\n\n'),
      cta: brief.primary_cta,
      disclaimer: disclaimer(),
      hashtags: []
    },
    evidence_refs: baseEvidenceRefs(),
    review_notes: ['Dry-run determinístico: revisar naturalidade da locução e duração final.']
  };
}

const deliverables = list(brief.deliverables).map((spec) => {
  if (spec.content_mode === 'CAROUSEL') return carouselDeliverable(spec);
  if (spec.content_mode === 'SHORT_VIDEO') return videoDeliverable(spec);
  return staticDeliverable(spec);
});

return [{
  json: {
    ...data,
    content_constitution: {
      constitution_version: '1.0.0',
      strategic_core: {
        objective: brief.objective,
        audience_insight: text(brief.audience?.segment, 'Público definido no briefing'),
        central_proposition: centralProposition,
        message_angle: offer ? 'oferta_confirmada' : 'institucional_seguro',
        tone: brief.brand?.voice,
        primary_cta: brief.primary_cta
      },
      message_hierarchy: [
        {
          priority: 1,
          role: 'primary',
          text: text(offer?.title, topic),
          evidence_refs: [text(offer?.ref_id, text(fact?.ref_id))].filter(Boolean)
        },
        {
          priority: 2,
          role: 'support',
          text: centralProposition,
          evidence_refs: [text(claim?.ref_id, text(fact?.ref_id))].filter(Boolean)
        },
        {
          priority: 3,
          role: 'action',
          text: brief.primary_cta,
          evidence_refs: [text(fact?.ref_id)].filter(Boolean)
        }
      ],
      deliverables,
      mandatory_copy: list(brief.required_disclaimers),
      forbidden_copy: list(brief.forbidden_copy),
      review: {
        required: true,
        reasons: ['Dry-run: copy criada sem chamada ao modelo e deve passar por revisão editorial.']
      }
    },
    ccg20_generation_mode: 'DETERMINISTIC_DRY_RUN'
  },
  binary: $input.first().binary
}];

