parameters.jsCode:
const incomingItem = $input.first();
const incoming = incomingItem.json || {};

let preparedItem = incomingItem;
try {
  preparedItem = $('CCG-20 Prepare Copy Brief').first();
} catch {}

const base = preparedItem.json || incoming;
const request = base.production_request || {};
const foundation = base.factual_foundation || {};
const brief = base.copy_brief || {};

function text(value, fallback = '') {
  if (value === undefined || value === null) return fallback;
  return String(value).trim();
}

function list(value) {
  return Array.isArray(value) ? value : [];
}

function objectValue(value) {
  return value && typeof value === 'object' && !Array.isArray(value) ? value : {};
}

function unique(values) {
  return [...new Set(values.map((value) => text(value)).filter(Boolean))];
}

function unwrapAi(value) {
  if (value && value.content_constitution) return value;
  if (value && value.output && typeof value.output === 'object') return value.output;
  if (value && typeof value.text === 'string') {
    try {
      return JSON.parse(value.text);
    } catch {}
  }
  if (value && typeof value.output === 'string') {
    try {
      return JSON.parse(value.output);
    } catch {}
  }
  return value || {};
}

function normalizeToken(value) {
  return text(value).toLowerCase().replace(/\s+/g, ' ').trim();
}

function truncate(value, max) {
  const source = text(value);
  if (!Number.isFinite(Number(max)) || source.length <= Number(max)) return source;
  return source.slice(0, Math.max(0, Number(max) - 1)).trimEnd() + '…';
}

function extractNumericTokens(value) {
  const source = text(value);
  const matches = source.match(
    /R\$\s*\d{1,3}(?:\.\d{3})*(?:,\d{1,2})?|\b\d+(?:[.,]\d+)?\s*(?:x|%|ml|mL|unidades?|sessões?|dias?|semanas?|meses?|horas?|minutos?)\b/gi
  ) || [];
  return matches.map(normalizeToken);
}

function safeRefIds(value) {
  const allowed = new Set(list(brief.allowed_reference_ids).map(text));
  return unique(list(value)).filter((id) => allowed.has(id));
}

const references = list(brief.approved_references);
const referenceMap = new Map(references.map((reference) => [text(reference.ref_id), reference]));
const primaryOffer = references.find((reference) => reference.kind === 'offer');
const primaryClaim = references.find((reference) => reference.kind === 'claim');
const primaryFact = references.find((reference) => reference.kind === 'fact');
const requiredDisclaimer = list(brief.required_disclaimers).join(' ');
const lockedCta = text(brief.primary_cta, request.cta);
const topic = text(brief.procedure_or_topic, text(primaryOffer?.title, text(brief.brand?.brand_name, 'Campanha')));
const allowedNumeric = new Set(list(brief.allowed_numeric_tokens).map(normalizeToken));
const blockedFragments = list(brief.blocked_fragments).map(normalizeToken).filter((fragment) => fragment.length >= 4);

const absolutePatterns = [
  { code: 'GUARANTEED_RESULT', regex: /\bgarant(?:e|ia|ido|ida|imos|ir)\b/i },
  { code: 'ABSOLUTE_PERCENT', regex: /\b100\s*%\b/i },
  { code: 'NO_RISK', regex: /\bsem\s+risco\b/i },
  { code: 'CURE', regex: /\bcura(?:r|do|da)?\b/i },
  { code: 'DEFINITIVE_RESULT', regex: /\bresultado\s+(?:certo|definitivo|permanente|garantido)\b/i }
];

function fallbackForField(field, refs) {
  if (field === 'cta') return lockedCta;
  if (field === 'disclaimer') return requiredDisclaimer;
  if (field === 'headline' || field === 'hook' || field === 'on_screen_text') {
    return text(primaryOffer?.title, topic);
  }
  if (field === 'subheadline') {
    return [
      text(primaryOffer?.price),
      text(primaryOffer?.payment_terms),
      text(primaryOffer?.conditions)
    ].filter(Boolean).join(' · ');
  }
  if (field === 'voiceover' || field === 'body') {
    return text(
      primaryClaim?.text,
      text(primaryFact?.text, `Conheça ${topic}.`)
    );
  }
  return text(primaryFact?.text, `Conheça ${topic}.`);
}

const sanitizationLog = [];
const reviewReasons = [];
const hardBlockers = [];

function sanitizeCopy(value, path, field, refs) {
  let source = text(value);
  const original = source;
  const reasons = [];

  if (field === 'cta') source = lockedCta;
  if (field === 'disclaimer' && requiredDisclaimer) {
    source = source
      ? unique([source, ...list(brief.required_disclaimers)]).join(' ')
      : requiredDisclaimer;
  }

  for (const pattern of absolutePatterns) {
    if (pattern.regex.test(source)) reasons.push(pattern.code);
  }

  const normalized = normalizeToken(source);
  for (const fragment of blockedFragments) {
    if (fragment && normalized.includes(fragment)) {
      reasons.push('BLOCKED_FRAGMENT');
      break;
    }
  }

  for (const token of extractNumericTokens(source)) {
    if (!allowedNumeric.has(token)) {
      reasons.push(`UNSUPPORTED_NUMERIC_TOKEN:${token}`);
    }
  }

  if (reasons.length) {
    source = fallbackForField(field, refs);
    sanitizationLog.push({
      path,
      original,
      replacement: source,
      reasons: unique(reasons)
    });
    reviewReasons.push(`Copy sanitizada em ${path}: ${unique(reasons).join(', ')}`);
  }

  return source;
}

function fallbackSlides(spec) {
  const refs = [
    text(primaryOffer?.ref_id),
    text(primaryClaim?.ref_id),
    text(primaryFact?.ref_id)
  ].filter(Boolean);

  const slides = [
    {
      sequence: 1,
      role: 'hook',
      headline: text(primaryOffer?.title, topic),
      body: '',
      cta: '',
      evidence_refs: [text(primaryOffer?.ref_id, text(primaryFact?.ref_id))].filter(Boolean)
    },
    {
      sequence: 2,
      role: 'value',
      headline: 'Informação aprovada',
      body: text(primaryClaim?.text, text(primaryFact?.text, `Conheça ${topic}.`)),
      cta: '',
      evidence_refs: [text(primaryClaim?.ref_id, text(primaryFact?.ref_id))].filter(Boolean)
    },
    {
      sequence: 3,
      role: 'cta',
      headline: lockedCta,
      body: requiredDisclaimer,
      cta: lockedCta,
      evidence_refs: [text(primaryFact?.ref_id)].filter(Boolean)
    }
  ];

  while (slides.length < Number(spec.slide_count || 3)) {
    slides.splice(slides.length - 1, 0, {
      sequence: slides.length,
      role: 'support',
      headline: 'Planejamento individual',
      body: requiredDisclaimer || `Conheça ${topic}.`,
      cta: '',
      evidence_refs: refs
    });
  }

  return slides.slice(0, Math.max(3, Number(spec.slide_count || 3))).map((slide, index) => ({
    ...slide,
    sequence: index + 1
  }));
}

function fallbackScenes(spec) {
  const count = Math.max(3, Number(spec.scene_count || 4));
  const total = Math.max(6, Number(spec.duration_seconds || 20));
  const duration = Math.max(2, Math.floor(total / count));
  const refs = [
    text(primaryOffer?.ref_id),
    text(primaryClaim?.ref_id),
    text(primaryFact?.ref_id)
  ].filter(Boolean);

  const scenes = [
    {
      role: 'hook',
      voiceover: text(primaryOffer?.title, topic),
      on_screen_text: text(primaryOffer?.title, topic),
      evidence_refs: [text(primaryOffer?.ref_id, text(primaryFact?.ref_id))].filter(Boolean)
    },
    {
      role: 'value',
      voiceover: text(primaryClaim?.text, text(primaryFact?.text, `Conheça ${topic}.`)),
      on_screen_text: text(primaryClaim?.text, text(primaryFact?.text, `Conheça ${topic}.`)),
      evidence_refs: [text(primaryClaim?.ref_id, text(primaryFact?.ref_id))].filter(Boolean)
    },
    {
      role: 'cta',
      voiceover: lockedCta,
      on_screen_text: lockedCta,
      evidence_refs: [text(primaryFact?.ref_id)].filter(Boolean)
    }
  ];

  while (scenes.length < count) {
    scenes.splice(scenes.length - 1, 0, {
      role: 'support',
      voiceover: requiredDisclaimer || `Conheça ${topic}.`,
      on_screen_text: requiredDisclaimer || `Conheça ${topic}.`,
      evidence_refs: refs
    });
  }

  return scenes.slice(0, count).map((scene, index) => ({
    sequence: index + 1,
    role: scene.role,
    duration_seconds: index === count - 1
      ? Math.max(2, total - duration * (count - 1))
      : duration,
    voiceover: scene.voiceover,
    on_screen_text: scene.on_screen_text,
    evidence_refs: safeRefIds(scene.evidence_refs)
  }));
}

const parsed = unwrapAi(incoming);
const rawConstitution = objectValue(parsed.content_constitution || incoming.content_constitution);
const rawDeliverables = list(rawConstitution.deliverables);
const rawById = new Map(rawDeliverables.map((deliverable) => [text(deliverable.deliverable_id), deliverable]));
const copyRegistry = [];

function registerCopy(deliverableId, path, field, value, evidenceRefs) {
  const refs = safeRefIds(evidenceRefs);
  const invalidRefs = unique(list(evidenceRefs)).filter((id) => !refs.includes(text(id)));
  if (invalidRefs.length) {
    reviewReasons.push(`Referências removidas em ${deliverableId}.${path}: ${invalidRefs.join(', ')}`);
  }

  const finalText = sanitizeCopy(value, `${deliverableId}.${path}`, field, refs);
  const copyId = `${deliverableId}:${path.replace(/[^a-zA-Z0-9]+/g, '_').replace(/^_|_$/g, '').toLowerCase()}`;
  const sanitized = sanitizationLog.some((entry) => entry.path === `${deliverableId}.${path}`);

  copyRegistry.push({
    copy_id: copyId,
    deliverable_id: deliverableId,
    path,
    text: finalText,
    evidence_refs: refs,
    status: sanitized ? 'sanitized' : 'approved',
    reasons: sanitized
      ? sanitizationLog.find((entry) => entry.path === `${deliverableId}.${path}`)?.reasons || []
      : []
  });

  return finalText;
}

const deliverables = list(brief.deliverables).map((spec) => {
  const raw = objectValue(rawById.get(text(spec.deliverable_id)));
  const limits = objectValue(spec.copy_limits);
  const sourceCopy = objectValue(raw.copy);
  const sourceCaption = objectValue(raw.caption);

  const defaultRefs = safeRefIds(
    list(raw.evidence_refs).length
      ? raw.evidence_refs
      : [
          text(primaryOffer?.ref_id),
          text(primaryClaim?.ref_id),
          text(primaryFact?.ref_id)
        ].filter(Boolean)
  );

  const copy = {
    headline: truncate(registerCopy(
      spec.deliverable_id,
      'copy.headline',
