    '9:16': { width: 1080, height: 1920, aspect_ratio: '9:16', safe_area: { top_pct: 10, right_pct: 6, bottom_pct: 18, left_pct: 6 } },
    '1080x1920': { width: 1080, height: 1920, aspect_ratio: '9:16', safe_area: { top_pct: 10, right_pct: 6, bottom_pct: 18, left_pct: 6 } },
    '4:5': { width: 1080, height: 1350, aspect_ratio: '4:5', safe_area: { top_pct: 6, right_pct: 6, bottom_pct: 8, left_pct: 6 } },
    '1080x1350': { width: 1080, height: 1350, aspect_ratio: '4:5', safe_area: { top_pct: 6, right_pct: 6, bottom_pct: 8, left_pct: 6 } },
    '3:4': { width: 1080, height: 1440, aspect_ratio: '3:4', safe_area: { top_pct: 6, right_pct: 6, bottom_pct: 8, left_pct: 6 } },
    '1:1': { width: 1080, height: 1080, aspect_ratio: '1:1', safe_area: { top_pct: 7, right_pct: 7, bottom_pct: 8, left_pct: 7 } },
