const data = item.json || {};
const request = data.production_request || {};
const manifest = data.asset_manifest || {};
const blueprint = data.creative_blueprint || {};

const text = (value, fallback = '') => value === undefined || value === null ? fallback : String(value).trim();
const list = (value) => Array.isArray(value) ? value : [];
const obj = (value) => value && typeof value === 'object' && !Array.isArray(value) ? value : {};
const unique = (values) => [...new Set(values.map((value) => text(value)).filter(Boolean))];
const clamp = (value, fallback, min, max) => {
  const number = Number(value);
  return Number.isFinite(number) ? Math.max(min, Math.min(max, number)) : fallback;
};

function safeZone(zoneValue, index, canvas, frameId) {
  const zone = obj(zoneValue);
  const safe = obj(canvas.safe_area);
  return {
    zone_id: text(zone.zone_id, `${frameId}:zone:${index + 1}`),
    purpose: text(zone.purpose, index === 0 ? 'primary_copy' : 'secondary_copy'),
    x_pct: clamp(zone.x_pct, 7, 0, 95),
    y_pct: clamp(zone.y_pct, 12, 0, 95),
    width_pct: clamp(zone.width_pct, 80, 5, 100),
    height_pct: clamp(zone.height_pct, 20, 3, 100),
    alignment: ['left','center','right'].includes(text(zone.alignment).toLowerCase()) ? text(zone.alignment).toLowerCase() : 'left',
    safe_area: safe
  };
}

function chooseZone(copyEntry, zones, index) {
  const path = text(copyEntry.path).toLowerCase();
  const purposeMatch = (keywords) => zones.find((zone) => keywords.some((keyword) => text(zone.purpose).toLowerCase().includes(keyword)));
  if (/cta|disclaimer/.test(path)) return purposeMatch(['cta','disclaimer','secondary']) || zones[zones.length - 1];
  if (/headline|hook|on_screen_text/.test(path)) return purposeMatch(['headline','primary','on_screen']) || zones[0];
  if (/subheadline|body|voiceover/.test(path)) return purposeMatch(['body','primary','secondary']) || zones[Math.min(index, zones.length - 1)];
  return zones[Math.min(index, zones.length - 1)];
}

const assetMap = new Map(list(manifest.asset_registry).map((asset) => [text(asset.asset_id), asset]));
const generationByPlannedAsset = new Map(list(manifest.generation_jobs).map((job) => [text(job.planned_asset_id), job]));
const generationByResolution = new Map(list(manifest.generation_jobs).map((job) => [text(job.resolution_id), job]));
const retrievalByAsset = new Map();
for (const job of list(manifest.retrieval_jobs)) {
  const assetId = text(job.asset_id);
  if (!retrievalByAsset.has(assetId)) retrievalByAsset.set(assetId, []);
  retrievalByAsset.get(assetId).push(job);
}

const variantMap = new Map();
for (const deliverable of list(blueprint.deliverable_blueprints)) {
  for (const variant of list(deliverable.variants)) {
    const blueprintId = text(variant.blueprint_id || variant.variant_id);
    variantMap.set(blueprintId, {
      deliverable,
      variant,
      frameMap: new Map(list(variant.frames).map((frame) => [text(frame.frame_id), frame]))
    });
  }
}

const allowedCopyIds = new Set(list(blueprint.copy_render_policy?.allowed_copy_ids).map(text));
const compositionJobs = list(manifest.composition_jobs)
  .slice()
  .sort((a, b) => text(a.blueprint_id).localeCompare(text(b.blueprint_id)) || Number(a.sequence) - Number(b.sequence));

const canonicalScenes = compositionJobs.map((jobValue) => {
  const job = obj(jobValue);
  const variantContext = variantMap.get(text(job.blueprint_id)) || {};
  const frame = obj(variantContext.frameMap?.get(text(job.frame_id)));
  const canvas = obj(job.canvas);
  const zones = list(job.overlay_zones).map((zone, index) => safeZone(zone, index, canvas, text(job.frame_id)));
  const validRenderText = list(job.render_text).filter((entry) => {
    const copyId = text(entry.copy_id);
    return list(job.copy_ids).includes(copyId) && (!allowedCopyIds.size || allowedCopyIds.has(copyId));
  });
  const copyLayers = validRenderText.map((entry, index) => {
    const zone = chooseZone(entry, zones, index) || safeZone({}, index, canvas, text(job.frame_id));
    const path = text(entry.path);
    let role = 'body';
    if (/headline|hook|on_screen_text/i.test(path)) role = 'headline';
    else if (/cta/i.test(path)) role = 'cta';
    else if (/disclaimer/i.test(path)) role = 'disclaimer';
    else if (/subheadline/i.test(path)) role = 'subheadline';
    else if (/voiceover/i.test(path)) role = 'voiceover';
    return {
      layer_id: `${text(job.frame_id)}:copy:${index + 1}`,
      copy_id: text(entry.copy_id),
      text: text(entry.text),
      path,
      role,
      zone_id: zone.zone_id,
      order: index + 1,
      alignment: zone.alignment,
      max_lines: role === 'headline' ? 3 : role === 'disclaimer' ? 3 : 5,
      fit_policy: 'shrink_within_limits_never_rewrite'
    };
  });

  const assetBindings = {};
  const retrievalJobIds = [];
  const generationJobIds = [];
  for (const [role, bindingValue] of Object.entries(obj(job.asset_bindings))) {
    const binding = obj(bindingValue);
    const assetId = text(binding.asset_id);
    const asset = assetMap.get(assetId);
    const generation = generationByPlannedAsset.get(assetId) || generationByResolution.get(text(binding.resolution_id));
    const retrieval = retrievalByAsset.get(assetId) || [];
    retrievalJobIds.push(...retrieval.map((entry) => text(entry.job_id)));
    if (generation) generationJobIds.push(text(generation.job_id));
    assetBindings[role] = {
      role,
      resolution_id: text(binding.resolution_id),
      asset_id: assetId,
      binding_status: text(binding.status),
      source_kind: asset ? 'existing' : generation ? 'planned_generation' : 'unknown',
      asset_type: text(asset?.asset_type || generation?.requested_asset_type),
      availability: text(asset?.availability, generation ? 'PLANNED_GENERATION' : ''),
      binary_key: text(asset?.binary_key),
      locator: text(asset?.locator),
      retrieval_job_ids: retrieval.map((entry) => text(entry.job_id)),
      generation_job_id: text(generation?.job_id),
      rights_status: text(asset?.rights_status),
      consent_status: text(asset?.consent_status)
    };
  }

  const contentMode = text(job.content_mode);
  const sceneType = ['SHORT_VIDEO', 'HYBRID'].includes(contentMode) ? 'VIDEO_SCENE' : contentMode === 'CAROUSEL' ? 'CAROUSEL_PAGE' : 'STATIC_FRAME';
  return {
    scene_id: `${text(job.blueprint_id)}:scene:${Number(job.sequence)}`,
    production_id: `${text(job.blueprint_id)}:production`,
    composition_job_id: text(job.job_id),
    blueprint_id: text(job.blueprint_id),
    deliverable_id: text(job.deliverable_id),
    variant_key: text(job.variant_key),
    frame_id: text(job.frame_id),
    sequence: Number(job.sequence),
    scene_type: sceneType,
    content_mode: contentMode,
    role: text(frame.role, Number(job.sequence) === 1 ? 'hook' : 'support'),
    duration_seconds: ['SHORT_VIDEO', 'HYBRID'].includes(contentMode) ? Math.max(1, Number(job.duration_seconds || frame.duration_seconds || 3)) : 0,
    canvas,
    immutable: {
      composition_job_id: text(job.job_id),
      copy_ids: unique(list(job.copy_ids)),
      asset_binding_roles: Object.keys(assetBindings),
      duration_seconds: ['SHORT_VIDEO', 'HYBRID'].includes(contentMode) ? Math.max(1, Number(job.duration_seconds || frame.duration_seconds || 3)) : 0,
      sequence: Number(job.sequence),
      canvas
    },
    source_direction: {
      visual_intent: text(frame.visual_intent),
      composition: text(frame.composition),
      motion_hint: text(frame.motion_hint),
      transition_hint: text(frame.transition_hint)
    },
    asset_bindings: assetBindings,
    copy_ids: unique(list(job.copy_ids)),
    copy_layers: copyLayers,
    overlay_zones: zones,
    dependencies: {
      retrieval_job_ids: unique(retrievalJobIds),
      generation_job_ids: unique(generationJobIds),
      composition_job_id: text(job.job_id)
    },
    policies: {
      render_text_in_base_asset: false,
      render_logo_in_base_asset: false,
      official_logo_only: true,
      copy_source: 'CCG-20_COPY_REGISTRY',
      publish_allowed: false
    }
  };
});

const productions = [];
for (const [blueprintId, context] of variantMap.entries()) {
  const scenes = canonicalScenes.filter((scene) => scene.blueprint_id === blueprintId).sort((a, b) => a.sequence - b.sequence);
  if (!scenes.length) continue;
  const totalDuration = scenes.reduce((sum, scene) => sum + Number(scene.duration_seconds || 0), 0);
  productions.push({
    production_id: `${blueprintId}:production`,
    blueprint_id: blueprintId,
    deliverable_id: text(context.deliverable?.deliverable_id),
    variant_key: text(context.variant?.variant_key),
    concept_label: text(context.variant?.concept_label),
    content_mode: text(context.deliverable?.content_mode),
    format: text(context.deliverable?.format),
    canvas: obj(context.deliverable?.canvas),
    scene_count: scenes.length,
    total_duration_seconds: totalDuration,
    scenes,
    creative_context: {
      visual_strategy: text(context.variant?.visual_strategy),
      layout_system: obj(context.variant?.layout_system),
      qa_requirements: unique(list(context.variant?.qa_requirements)),
      review_notes: unique(list(context.variant?.review_notes))
    }
  });
}

const brief = {
  brief_version: '1.0.0',
  run_id: text(data.ccg_context?.run_id),
  campaign_id: text(request.campaign_id),
  content_id: text(request.content_id),
  production_tier: text(request.production_tier),
  objective: text(request.objective),
  procedure_or_topic: text(request.procedure_or_topic),
  creative_system: obj(blueprint.creative_system),
  productions,
  asset_registry_ids: list(manifest.asset_registry).map((asset) => text(asset.asset_id)),
  planned_asset_ids: list(manifest.generation_jobs).map((job) => text(job.planned_asset_id)),
  generation_job_ids: list(manifest.generation_jobs).map((job) => text(job.job_id)),
  retrieval_job_ids: list(manifest.retrieval_jobs).map((job) => text(job.job_id)),
  composition_job_ids: list(manifest.composition_jobs).map((job) => text(job.job_id)),
  allowed_copy_ids: unique(canonicalScenes.flatMap((scene) => scene.copy_ids)),
  forbidden_visuals: unique(list(blueprint.forbidden_visuals)),
  scene_policy: {
    ai_may_edit_direction_only: true,
    immutable_ids_order_duration_canvas_copy_and_bindings: true,
    no_new_scenes: true,
    no_removed_scenes: true,
    no_new_assets: true,
    no_new_copy: true,
    no_text_or_logo_in_base_assets: true,
    simple_transitions_only: true,
    human_approval_required: true,
    publish_allowed: false
  },
  upstream_status: {
    asset_manifest_status: text(manifest.status),
    routing_decision: text(manifest.routing_decision),
    review_reasons: unique(list(manifest.review?.reasons))
  },
  prepared_at: new Date().toISOString()
};

return [{
  json: {
    ...data,
    scene_planning_brief: brief,
    ccg50_preparation: {
      productions: productions.length,
      scenes: canonicalScenes.length,
      video_scenes: canonicalScenes.filter((scene) => scene.scene_type === 'VIDEO_SCENE').length,
      carousel_pages: canonicalScenes.filter((scene) => scene.scene_type === 'CAROUSEL_PAGE').length,
      static_frames: canonicalScenes.filter((scene) => scene.scene_type === 'STATIC_FRAME').length,
      retrieval_dependencies: unique(canonicalScenes.flatMap((scene) => scene.dependencies.retrieval_job_ids)).length,
      generation_dependencies: unique(canonicalScenes.flatMap((scene) => scene.dependencies.generation_job_ids)).length,
      prepared_at: brief.prepared_at
    }
  },
  binary: item.binary
}];

const item = $input.first();
const data = item.json || {};
const brief = data.scene_planning_brief || {};
const text = (value, fallback = '') => value === undefined || value === null ? fallback : String(value).trim();
const list = (value) => Array.isArray(value) ? value : [];

function directionFor(scene, production) {
  const role = text(scene.role).toLowerCase();
  const mode = text(scene.content_mode);
  let shotType = 'editorial medium shot';
  let framing = 'subject positioned on one third with clean negative space for overlays';
  let subjectAction = 'natural, calm and credible presence';
  let cameraMotion = 'locked';
  let lighting = 'soft diffused premium lighting with natural skin texture';
  let environment = 'clean contemporary aesthetic clinic environment with discreet depth';

  if (role === 'hook') {
    shotType = mode === 'SHORT_VIDEO' ? 'medium close-up hero shot' : 'hero editorial composition';
    subjectAction = 'direct, confident and welcoming presence establishing the campaign theme';
    cameraMotion = mode === 'SHORT_VIDEO' ? 'slow_push_in' : 'locked';
  } else if (['value','benefit','support'].includes(role)) {
    shotType = mode === 'SHORT_VIDEO' ? 'detail-to-medium contextual shot' : 'balanced supporting composition';
    subjectAction = 'subtle interaction with the environment or symbolic treatment element';
    cameraMotion = mode === 'SHORT_VIDEO' ? 'gentle_pan' : 'locked';
  } else if (['offer','price'].includes(role)) {
    shotType = 'clean information-supporting composition';
    framing = 'visual subject reduced to preserve generous high-contrast overlay space';
    cameraMotion = mode === 'SHORT_VIDEO' ? 'subtle_parallax' : 'locked';
  } else if (role === 'cta') {
    shotType = 'welcoming closing hero shot';
    framing = 'open composition with clear CTA zone and official logo area';
    subjectAction = 'calm closing expression and subtle invitation gesture';
    cameraMotion = mode === 'SHORT_VIDEO' ? 'slow_pull_out' : 'locked';
  }

  return {
    scene_id: scene.scene_id,
    visual_direction: {
      environment,
      subject: `Natural and premium subject coherent with ${text(brief.procedure_or_topic, 'the approved campaign topic')}.`,
      subject_action: subjectAction,
      shot_type: shotType,
      framing,
      camera_angle: 'eye-level or slightly above eye-level, natural perspective',
      camera_motion: cameraMotion,
      lighting,
      depth_and_focus: 'clean focal separation with natural depth and realistic skin texture',
      color_and_materials: 'follow the approved campaign palette and material language',
      composition_notes: text(scene.source_direction?.composition, 'preserve safe areas and negative space for downstream overlays'),
      continuity_notes: `Maintain the same visual family, subject treatment, palette and lighting across ${production.production_id}.`
    },
    transition_in: scene.sequence === 1 ? 'none' : (mode === 'SHORT_VIDEO' ? 'cut' : 'none'),
    transition_out: scene.sequence === production.scene_count ? 'none' : (mode === 'SHORT_VIDEO' ? 'cut' : 'none'),
    production_notes: [
      'Base visual only; text and official logo are composed downstream.',
      'Do not change copy, duration, asset bindings, canvas or sequence.'
    ]
  };
}

const productions = list(brief.productions).map((production) => ({
  production_id: production.production_id,
  continuity: {
    visual_anchor: text(production.concept_label, 'approved creative concept'),
    environment_continuity: 'same campaign universe with controlled variation between frames',
    subject_continuity: 'consistent identity, natural appearance and styling when the same subject is used',
    lighting_continuity: 'consistent color temperature, contrast and skin treatment',
    palette_continuity: 'use only the palette and material language from the creative system',
    typography_continuity: 'text remains a downstream overlay and follows one hierarchy system',
    pacing: production.content_mode === 'SHORT_VIDEO' ? 'clear opening, concise development and calm CTA close' : 'progressive visual hierarchy without repetition'
  },
  scene_treatments: list(production.scenes).map((scene) => directionFor(scene, production)),
  review_notes: []
}));

return [{
  json: {
    ...data,
    scene_direction_proposal: {
      proposal_version: '1.0.0',
      productions,
      review: { required: false, reasons: [] }
    },
    ccg50_generation_mode: 'DETERMINISTIC_DRY_RUN'
  },
  binary: item.binary
}];

parameters.text:
=Detalhe a direção das cenas e retorne SOMENTE o JSON exigido pelo parser.

Scene planning brief fechado:
{{ JSON.stringify($json.scene_planning_brief) }}

parameters.jsCode:
const incomingItem = $input.first();
const incoming = incomingItem.json || {};
let preparedItem = incomingItem;
try { preparedItem = $('CCG-50 Prepare Scene Planning Brief').first(); } catch {}
const base = preparedItem.json || incoming;
const request = base.production_request || {};
const brief = base.scene_planning_brief || {};
const manifest = base.asset_manifest || {};

const text = (value, fallback = '') => value === undefined || value === null ? fallback : String(value).trim();
const list = (value) => Array.isArray(value) ? value : [];
const obj = (value) => value && typeof value === 'object' && !Array.isArray(value) ? value : {};
const unique = (values) => [...new Set(values.map((value) => text(value)).filter(Boolean))];

function unwrap(value) {
  if (value?.scene_direction_proposal) return value;
  if (value?.output && typeof value.output === 'object') return value.output;
  for (const candidate of [value?.text, value?.output]) {
    if (typeof candidate === 'string') { try { return JSON.parse(candidate); } catch {} }
  }
  return value || {};
}

function clean(value) {
  return text(value)
    .replace(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi, '[EMAIL_REDACTED]')
    .replace(/(?:\+?55\s*)?(?:\(?\d{2}\)?\s*)?(?:9?\d{4})[-.\s]?\d{4}/g, '[PHONE_REDACTED]')
    .replace(/\b\d{3}\.?\d{3}\.?\d{3}-?\d{2}\b/g, '[CPF_REDACTED]');
}

const unsafePatterns = [
  { code: 'TEXT_IN_BASE_ASSET', regex: /\b(?:render|include|write|show|add)\b[^.]{0,60}\b(?:text|words?|letters?|numbers?|price|logo)\b/i },
  { code: 'BEFORE_AFTER', regex: /\bantes\s*e\s*depois\b|\bbefore\s*(?:and|&)\s*after\b/i },
  { code: 'GUARANTEED_RESULT', regex: /\b(?:resultado\s+garantido|garantia\s+de\s+resultado|guaranteed\s+result)\b/i },
  { code: 'GRAPHIC_PROCEDURE', regex: /\b(?:blood|sangue|open wound|ferida aberta|needle close-up|agulha em destaque)\b/i },
  { code: 'UNREAL_ANATOMY', regex: /\b(?:distorted anatomy|anatomia irreal|plastic skin|pele plástica)\b/i }
];

function safeDirection(value, fallback, path, sanitizationLog) {
  let output = clean(value);
  const reasons = [];
  for (const pattern of unsafePatterns) {
    if (pattern.regex.test(output)) reasons.push(pattern.code);
  }
  if (reasons.length) {
    output = fallback;
    sanitizationLog.push({ path, reasons: unique(reasons) });
  }
  return output || fallback;
}

const allowedTransitions = new Set(['none','cut','dissolve','fade','match_cut']);
const allowedMotion = new Set(['locked','slow_push_in','slow_pull_out','gentle_pan','subtle_parallax','handheld_subtle']);
const parsed = unwrap(incoming);
const proposal = obj(parsed.scene_direction_proposal || incoming.scene_direction_proposal);
const proposedProductionMap = new Map(list(proposal.productions).map((production) => [text(production.production_id), production]));
const registryIds = new Set(list(manifest.asset_registry).map((asset) => text(asset.asset_id)));
const plannedAssetIds = new Set(list(manifest.generation_jobs).map((job) => text(job.planned_asset_id)));
const retrievalJobIds = new Set(list(manifest.retrieval_jobs).map((job) => text(job.job_id)));
const generationJobIds = new Set(list(manifest.generation_jobs).map((job) => text(job.job_id)));
const compositionJobIds = new Set(list(manifest.composition_jobs).map((job) => text(job.job_id)));
const allowedCopyIds = new Set(list(brief.allowed_copy_ids).map(text));
const reviewReasons = [
  ...list(base.ccg50_input_validation?.warnings),
  ...list(brief.upstream_status?.review_reasons),
  ...list(proposal.review?.reasons)
];
const hardBlockers = [];
const sanitizationLog = [];
const sceneRegistry = [];

const productions = list(brief.productions).map((canonicalProduction) => {
  const proposedProduction = obj(proposedProductionMap.get(text(canonicalProduction.production_id)));
  const treatmentMap = new Map(list(proposedProduction.scene_treatments).map((treatment) => [text(treatment.scene_id), treatment]));
  const mode = text(canonicalProduction.content_mode);
  const productionScenes = list(canonicalProduction.scenes).map((canonicalScene) => {
    const proposed = obj(treatmentMap.get(text(canonicalScene.scene_id)));
    const direction = obj(proposed.visual_direction);
    const fallbackDirection = {
      environment: 'clean contemporary aesthetic clinic environment with discreet depth',
      subject: `Natural and premium subject coherent with ${text(brief.procedure_or_topic, 'the approved campaign topic')}.`,
      subject_action: 'natural, calm and credible presence',
      shot_type: mode === 'SHORT_VIDEO' ? 'editorial medium shot' : 'balanced editorial composition',
      framing: 'preserve clean negative space and approved overlay zones',
      camera_angle: 'eye-level, natural perspective',
      camera_motion: mode === 'SHORT_VIDEO' ? 'locked' : 'locked',
      lighting: 'soft diffused premium lighting with natural skin texture',
      depth_and_focus: 'clean focal separation with natural depth and realistic skin texture',
      color_and_materials: 'follow the approved campaign palette and material language',
      composition_notes: text(canonicalScene.source_direction?.composition, 'preserve safe areas and negative space'),
      continuity_notes: `Maintain the approved visual family across ${canonicalProduction.production_id}.`
    };

    let cameraMotion = text(direction.camera_motion, fallbackDirection.camera_motion).toLowerCase().replace(/\s+/g, '_');
    if (mode !== 'SHORT_VIDEO') cameraMotion = 'locked';
    else if (!allowedMotion.has(cameraMotion)) {
      sanitizationLog.push({ path: `${canonicalScene.scene_id}.visual_direction.camera_motion`, reasons: ['UNSUPPORTED_CAMERA_MOTION'] });
      cameraMotion = 'locked';
    }

    let transitionIn = text(proposed.transition_in, canonicalScene.sequence === 1 ? 'none' : mode === 'SHORT_VIDEO' ? 'cut' : 'none').toLowerCase().replace(/\s+/g, '_');
    let transitionOut = text(proposed.transition_out, canonicalScene.sequence === canonicalProduction.scene_count ? 'none' : mode === 'SHORT_VIDEO' ? 'cut' : 'none').toLowerCase().replace(/\s+/g, '_');
    if (mode !== 'SHORT_VIDEO') { transitionIn = 'none'; transitionOut = 'none'; }
    if (!allowedTransitions.has(transitionIn)) { sanitizationLog.push({ path: `${canonicalScene.scene_id}.transition_in`, reasons: ['UNSUPPORTED_TRANSITION'] }); transitionIn = 'cut'; }
    if (!allowedTransitions.has(transitionOut)) { sanitizationLog.push({ path: `${canonicalScene.scene_id}.transition_out`, reasons: ['UNSUPPORTED_TRANSITION'] }); transitionOut = 'cut'; }
    if (canonicalScene.sequence === 1) transitionIn = 'none';
    if (canonicalScene.sequence === canonicalProduction.scene_count) transitionOut = 'none';

    for (const binding of Object.values(obj(canonicalScene.asset_bindings))) {
      const assetId = text(binding.asset_id);
      if (!registryIds.has(assetId) && !plannedAssetIds.has(assetId)) hardBlockers.push(`UNKNOWN_ASSET_BINDING:${canonicalScene.scene_id}:${assetId}`);
      if (text(binding.binding_status) === 'BLOCKED') hardBlockers.push(`BLOCKED_ASSET_BINDING:${canonicalScene.scene_id}:${assetId}`);
      for (const jobId of list(binding.retrieval_job_ids)) if (!retrievalJobIds.has(text(jobId))) hardBlockers.push(`UNKNOWN_RETRIEVAL_JOB:${canonicalScene.scene_id}:${text(jobId)}`);
      if (text(binding.generation_job_id) && !generationJobIds.has(text(binding.generation_job_id))) hardBlockers.push(`UNKNOWN_GENERATION_JOB:${canonicalScene.scene_id}:${text(binding.generation_job_id)}`);
    }
    if (!compositionJobIds.has(text(canonicalScene.composition_job_id))) hardBlockers.push(`UNKNOWN_COMPOSITION_JOB:${canonicalScene.scene_id}`);
    for (const copyId of list(canonicalScene.copy_ids)) if (allowedCopyIds.size && !allowedCopyIds.has(text(copyId))) hardBlockers.push(`UNAUTHORIZED_COPY_ID:${canonicalScene.scene_id}:${text(copyId)}`);

    const finalScene = {
      scene_id: canonicalScene.scene_id,
      production_id: canonicalScene.production_id,
      composition_job_id: canonicalScene.composition_job_id,
      blueprint_id: canonicalScene.blueprint_id,
      deliverable_id: canonicalScene.deliverable_id,
      variant_key: canonicalScene.variant_key,
      frame_id: canonicalScene.frame_id,
      sequence: canonicalScene.sequence,
      scene_type: canonicalScene.scene_type,
      content_mode: canonicalScene.content_mode,
      role: canonicalScene.role,
      duration_seconds: canonicalScene.duration_seconds,
      canvas: canonicalScene.canvas,
      visual_direction: {
        environment: safeDirection(direction.environment, fallbackDirection.environment, `${canonicalScene.scene_id}.environment`, sanitizationLog),
        subject: safeDirection(direction.subject, fallbackDirection.subject, `${canonicalScene.scene_id}.subject`, sanitizationLog),
        subject_action: safeDirection(direction.subject_action, fallbackDirection.subject_action, `${canonicalScene.scene_id}.subject_action`, sanitizationLog),
