if (text(data.next_module) !== 'CCG-60') {
  errors.push(`Roteamento inválido: esperado CCG-60, recebido ${text(data.next_module, 'vazio')}.`);
}
if (!['READY', 'NEEDS_REVIEW'].includes(text(manifest?.status))) {
  errors.push(`scene_manifest.status não permite planejamento de áudio: ${text(manifest?.status, 'vazio')}.`);
}
if (!['PROCEED', 'PROCEED_WITH_GUARDRAILS'].includes(text(manifest?.routing_decision))) {
  errors.push(`routing_decision não permite planejamento de áudio: ${text(manifest?.routing_decision, 'vazio')}.`);
