  errors.push('ccg_context.mode deve ser DRY_RUN ou LIVE.');
}
if (!list(manifest?.productions).length) errors.push('scene_manifest não possui productions.');

const productionIds = new Set();
const sceneIds = new Set();
for (const production of list(manifest?.productions)) {
  const productionId = text(production.production_id);
  if (!productionId) errors.push('Produção sem production_id.');
  else if (productionIds.has(productionId)) errors.push(`production_id duplicado: ${productionId}.`);
  productionIds.add(productionId);

  const scenes = list(production.scenes);
  if (Number(production.scene_count) !== scenes.length) {
    errors.push(`scene_count divergente em ${productionId}.`);
  }

  const sorted = scenes.slice().sort((a, b) => Number(a.sequence) - Number(b.sequence));
  sorted.forEach((scene, index) => {
    const sceneId = text(scene.scene_id);
    if (!sceneId) errors.push(`Cena sem scene_id em ${productionId}.`);
    else if (sceneIds.has(sceneId)) errors.push(`scene_id duplicado: ${sceneId}.`);
    sceneIds.add(sceneId);

    if (Number(scene.sequence) !== index + 1) {
      errors.push(`Sequência inválida em ${sceneId}.`);
    }
    if (text(scene.production_id) !== productionId) {
      errors.push(`Cena ${sceneId} pertence a production_id divergente.`);
    }
    if (text(production.content_mode) === 'SHORT_VIDEO' && Number(scene.duration_seconds) <= 0) {
      errors.push(`Cena de vídeo sem duração positiva: ${sceneId}.`);
    }
  });

  const duration = scenes.reduce((sum, scene) => sum + Number(scene.duration_seconds || 0), 0);
  if (Math.abs(duration - Number(production.total_duration_seconds || 0)) > 0.05) {
