const text = (value, fallback = '') => value === undefined || value === null ? fallback : String(value).trim();
const list = (value) => Array.isArray(value) ? value : [];
const obj = (value) => value && typeof value === 'object' && !Array.isArray(value) ? value : {};
const unique = (values) => [...new Set(values.map((value) => text(value)).filter(Boolean))];
const bool = (value, fallback) => typeof value === 'boolean' ? value : fallback;
const clamp = (value, fallback, min, max) => {
  const number = Number(value);
  return Number.isFinite(number) ? Math.max(min, Math.min(max, number)) : fallback;
};

function clean(value) {
  return text(value)
    .replace(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi, '[EMAIL_REDACTED]')
    .replace(/(?:\+?55\s*)?(?:\(?\d{2}\)?\s*)?(?:9?\d{4})[-.\s]?\d{4}/g, '[PHONE_REDACTED]')
    .replace(/\b\d{3}\.?\d{3}\.?\d{3}-?\d{2}\b/g, '[CPF_REDACTED]');
}

function approvedAudioAsset(asset) {
  const type = text(asset.asset_type || asset.type).toUpperCase();
  const role = text(asset.role).toLowerCase();
  const audioType = ['AUDIO', 'MUSIC', 'SFX', 'VOICE', 'VOICEOVER'].includes(type) ||
    ['music', 'music_bed', 'soundtrack', 'sfx', 'voice', 'voiceover'].includes(role);
  const rights = text(asset.rights_status || asset.license_status).toLowerCase();
  const usage = text(asset.usage_status || asset.approval_status).toLowerCase();
  const scope = text(asset.reference_usage_scope || asset.usage_scope).toUpperCase();
  const blockedRights = ['restricted', 'denied', 'revoked', 'expired', 'unknown'].includes(rights);
  const analyzeOnly = scope === 'ANALYZE_ONLY';
  return audioType && !blockedRights && !analyzeOnly &&
    !['blocked', 'rejected'].includes(usage) && asset.can_use !== false;
}

function words(value) {
