    sfx_enabled: applicable && sfxEnabled,
    captions_enabled: applicable && captionsEnabled && voiceoverEnabled,
    visual_dependencies: obj(production.dependencies)
  };
});

const ccgOptionalSkip = productions.length > 0 && !productions.some((production) => production.audio_applicable === true);

const brief = {
  brief_version: '1.0.0',
  run_id: text(data.ccg_context?.run_id),
  campaign_id: text(request.campaign_id),
  content_id: text(request.content_id),
  production_tier: text(request.production_tier, 'STANDARD'),
  locale,
  brand_voice: text(request.brand_context?.voice, 'premium, claro, humano e seguro'),
  voice_policy: {
    requested_mode: voiceMode,
    consent_status: text(consent.status, voiceMode === 'generic_synthetic' ? 'NOT_REQUIRED' : 'UNKNOWN').toUpperCase(),
    voice_id: text(consent.voice_id || prefs.voice_id),
    synthetic_voice_disclosure_required: voiceMode === 'generic_synthetic',
    speaking_rate: speakingRate,
    allowed_rate_range: [0.85, 1.15],
    lead_in_seconds: leadIn,
    lead_out_seconds: leadOut,
    preserve_copy_verbatim: true,
    cloning_without_consent_forbidden: true
  },
  music_policy: {
    original_only: true,
    instrumental_only: bool(prefs.instrumental_only, true),
    moods: unique(list(prefs.music_mood).length ? list(prefs.music_mood) : ['warm', 'optimistic', 'premium']),
    genre_family: unique(list(prefs.music_genre).length ? list(prefs.music_genre) : ['ambient-pop', 'organic-electronic']),
    preferred_bpm_range: [
      clamp(prefs.min_bpm, 88, 55, 160),
      clamp(prefs.max_bpm, 106, 55, 160)
    ].sort((a, b) => a - b),
    artist_imitation_forbidden: true,
    recognizable_melody_forbidden: true,
    recognizable_hook_forbidden: true,
    existing_usable_music_asset_ids: usableMusicAssets.map((asset) => asset.asset_id)
  },
  reference_policy: {
    references: referenceAssets,
    analyze_characteristics_only: true,
    restricted_material_blocked: true,
    copying_or_style_imitation_forbidden: true
  },
  technical_targets: {
    master_lufs: -14,
    true_peak_db: -1,
    sample_rate_hz: 48000,
    bit_depth: 24,
    speech_priority_ducking_db: -8,
    channels: 2,
    master_formats: ['wav', 'mp3'],
    caption_formats: ['srt', 'vtt']
  },
  audio_assets: audioAssets,
  productions,
  global_forbidden_audio: [
    'imitação de artista, música ou identidade vocal reconhecível',
    'melodia, hook ou letra protegida',
    'voz clonada sem consentimento verificável',
    'referência restrita usada como material de saída',
    'som de agulha, sangue, ferida ou procedimento gráfico',
    'efeitos assustadores, agressivos ou incompatíveis com a marca',
    'volume que prejudique a inteligibilidade da locução',
    'dados pessoais em prompts, metadados ou locução'
  ],
  production_policy: {
    provider_resolution: 'DEFERRED_TO_CCG_80',
    generate_audio_now: false,
    scene_ids_locked: true,
    duration_locked: true,
    voiceover_copy_locked: true,
    human_approval_required: true,
    publish_allowed: false
  },
  upstream_status: {
    scene_status: text(sceneManifest.status),
    routing_decision: text(sceneManifest.routing_decision),
    review_reasons: unique(list(sceneManifest.review?.reasons))
  },
  prepared_at: new Date().toISOString()
};

return [{
  json: {
    ...data,
    ccg_optional_modules: {
      ...(data.ccg_optional_modules || {}),
      CCG_60: ccgOptionalSkip
        ? { status: 'SKIPPED_NOT_REQUIRED', reason_code: 'CONTENT_MODE_NOT_APPLICABLE', module: 'CCG-60' }
        : { status: 'REQUIRED', module: 'CCG-60' }
    },
    audio_planning_brief: brief,
    ccg60_preparation: {
      productions: productions.length,
      video_productions: productions.filter((production) => production.audio_applicable).length,
      voiceover_segments: productions.reduce((sum, production) =>
        sum + production.scenes.filter((scene) => scene.voiceover_text).length, 0),
      usable_music_assets: usableMusicAssets.length,
      audio_references: referenceAssets.length,
      prepared_at: brief.prepared_at
    }
  },
  binary: item.binary
}];

const item = $input.first();
const data = item.json || {};
const brief = data.audio_planning_brief || {};

const text = (value, fallback = '') => value === undefined || value === null ? fallback : String(value).trim();
const list = (value) => Array.isArray(value) ? value : [];
const unique = (values) => [...new Set(values.map((value) => text(value)).filter(Boolean))];

function energyForRole(role) {
  const normalized = text(role).toLowerCase();
  if (normalized === 'hook') return 0.58;
  if (normalized === 'cta') return 0.45;
  if (['offer', 'value'].includes(normalized)) return 0.52;
  return 0.42;
}

const productions = list(brief.productions).map((production) => {
  if (!production.audio_applicable) {
    return {
      production_id: production.production_id,
      voice_profile: {
        enabled: false,
        mode: 'none',
        language: brief.locale,
        presentation: 'neutral',
        delivery_style: 'not_applicable',
        speaking_rate: 1
      },
      music_direction: {
        enabled: false,
        source_strategy: 'none',
        mood: [],
        genre_family: [],
        bpm_target: 0,
        instrumentation: [],
        energy_curve: [],
        originality_rules: []
      },
      scene_treatments: [],
      review_notes: []
    };
  }

  const voiceProfile = {
    enabled: production.voiceover_enabled,
    mode: production.voiceover_enabled ? brief.voice_policy.requested_mode : 'none',
    language: brief.locale,
    presentation: text(brief.voice_policy.requested_mode) === 'generic_synthetic' ? 'neutral' : 'as_authorized',
    delivery_style: 'warm, clear, confident and natural; no exaggerated advertising cadence',
    speaking_rate: Number(brief.voice_policy.speaking_rate || 1),
    pronunciation_notes: []
  };

  const existingMusic = list(brief.music_policy.existing_usable_music_asset_ids)[0] || '';
  const musicDirection = {
    enabled: production.music_enabled,
    source_strategy: !production.music_enabled ? 'none' : existingMusic ? 'reuse_licensed_asset' : 'generate_original',
    selected_asset_id: existingMusic,
    mood: list(brief.music_policy.moods),
    genre_family: list(brief.music_policy.genre_family),
    bpm_target: Math.round(
      (Number(brief.music_policy.preferred_bpm_range?.[0] || 88) +
       Number(brief.music_policy.preferred_bpm_range?.[1] || 106)) / 2
    ),
    meter: '4/4',
    instrumentation: ['soft percussion', 'warm keys', 'subtle pads', 'light bass'],
    energy_curve: production.scenes.map((scene) => ({
      scene_id: scene.scene_id,
      energy: energyForRole(scene.role)
    })),
    originality_rules: [
      'original composition only',
      'no recognizable melody or hook',
      'no artist imitation',
      'references are analyze-only'
    ]
  };

  const sceneTreatments = production.scenes.map((scene) => {
    const sfx = [];
    if (production.sfx_enabled && scene.sequence > 1) {
      sfx.push({
        cue_type: 'soft_transition',
        placement: 'scene_start',
        relative_time_seconds: 0,
        description: scene.transition_in === 'dissolve'
          ? 'very soft airy transition'
          : 'subtle clean transition accent',
        gain_db: -20
      });
    }

    return {
      scene_id: scene.scene_id,
      voice_delivery: {
        enabled: production.voiceover_enabled && Boolean(scene.voiceover_text),
        style: scene.role === 'hook'
          ? 'clear and inviting'
          : scene.role === 'cta'
            ? 'warm and direct'
            : 'calm and informative',
        emphasis_words: [],
        pause_before_seconds: Number(brief.voice_policy.lead_in_seconds || 0.18),
        pause_after_seconds: Number(brief.voice_policy.lead_out_seconds || 0.18)
      },
      music_energy: energyForRole(scene.role),
      music_action: scene.role === 'hook'
        ? 'gentle entrance'
        : scene.role === 'cta'
          ? 'soft resolution'
          : 'steady support under speech',
      sfx_cues: sfx,
      intentional_silence: {
        enabled: !production.voiceover_enabled && !production.music_enabled && !production.sfx_enabled,
        reason: !production.voiceover_enabled && !production.music_enabled && !production.sfx_enabled
          ? 'audio intentionally disabled'
          : ''
      },
      review_notes: []
    };
  });

  return {
    production_id: production.production_id,
    voice_profile: voiceProfile,
    music_direction: musicDirection,
    scene_treatments: sceneTreatments,
    review_notes: ['Dry-run determinístico: revisar escolha final de voz e trilha antes da renderização.']
  };
});

return [{
  json: {
    ...data,
    audio_direction_proposal: {
      proposal_version: '1.0.0',
      productions,
      review: {
        required: false,
        reasons: []
      }
    },
    ccg60_generation_mode: 'DETERMINISTIC_DRY_RUN'
  },
  binary: item.binary
}];

parameters.text:
=Crie a proposta de direção de áudio e retorne SOMENTE o JSON exigido pelo parser.

Audio planning brief fechado:
{{ JSON.stringify($json.audio_planning_brief) }}

parameters.jsCode:
const incomingItem = $input.first();
const incoming = incomingItem.json || {};
let preparedItem = incomingItem;
try { preparedItem = $('CCG-60 Prepare Audio Planning Brief').first(); } catch {}

const base = preparedItem.json || incoming;
const request = base.production_request || {};
const brief = base.audio_planning_brief || {};

const text = (value, fallback = '') => value === undefined || value === null ? fallback : String(value).trim();
const list = (value) => Array.isArray(value) ? value : [];
const obj = (value) => value && typeof value === 'object' && !Array.isArray(value) ? value : {};
const unique = (values) => [...new Set(values.map((value) => text(value)).filter(Boolean))];
const clamp = (value, fallback, min, max) => {
  const number = Number(value);
  return Number.isFinite(number) ? Math.max(min, Math.min(max, number)) : fallback;
};

function unwrap(value) {
  if (value?.audio_direction_proposal) return value;
  if (value?.output && typeof value.output === 'object') return value.output;
  for (const candidate of [value?.text, value?.output]) {
    if (typeof candidate === 'string') {
      try { return JSON.parse(candidate); } catch {}
    }
  }
  return value || {};
}

function clean(value) {
  return text(value)
    .replace(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi, '[EMAIL_REDACTED]')
    .replace(/(?:\+?55\s*)?(?:\(?\d{2}\)?\s*)?(?:9?\d{4})[-.\s]?\d{4}/g, '[PHONE_REDACTED]')
    .replace(/\b\d{3}\.?\d{3}\.?\d{3}-?\d{2}\b/g, '[CPF_REDACTED]');
}

function estimateSpeechSeconds(value, speed) {
  const source = clean(value);
  if (!source) return 0;
  const wordCount = source.split(/\s+/).filter(Boolean).length;
  const punctuationPauses = (source.match(/[,.!?;:]/g) || []).length * 0.1;
  return Number((wordCount / (2.25 * speed) + punctuationPauses).toFixed(2));
}

function stableId(prefix, parts) {
  const source = parts.map((value) => text(value)).join('|');
  let hash = 2166136261;
  for (let index = 0; index < source.length; index++) {
    hash ^= source.charCodeAt(index);
    hash = Math.imul(hash, 16777619);
  }
  return `${prefix}-${(hash >>> 0).toString(16).padStart(8, '0')}`;
}

const forbiddenImitation = /\b(?:imit(?:ar|ate)|igual\s+(?:a|ao)|no\s+estilo\s+de|sound\s+like|voice\s+of|voz\s+de)\b/i;
const restrictedAudio = /\b(?:agulha|needle|sangue|blood|ferida|wound|grito|scream|choque|shock)\b/i;
const allowedVoiceModes = new Set(['none', 'generic_synthetic', 'licensed_human', 'custom_identity', 'cloned']);
const allowedSourceStrategies = new Set(['none', 'reuse_licensed_asset', 'generate_original']);
const allowedCueTypes = new Set(['soft_transition', 'gentle_riser', 'soft_resolution', 'subtle_ui_accent', 'none']);

const parsed = unwrap(incoming);
const proposal = obj(parsed.audio_direction_proposal || incoming.audio_direction_proposal);
const proposedMap = new Map(list(proposal.productions).map((production) => [text(production.production_id), production]));

const reviewReasons = [
  ...list(base.ccg60_input_validation?.warnings),
  ...list(brief.upstream_status?.review_reasons),
  ...list(proposal.review?.reasons)
];
const hardBlockers = [];
const sanitizationLog = [];
const jobRegistry = [];
const licenseEntries = [];
const consentStatus = text(brief.voice_policy?.consent_status).toUpperCase();
const usableMusicIds = new Set(list(brief.music_policy?.existing_usable_music_asset_ids).map(text));
const audioAssetMap = new Map(list(brief.audio_assets).map((asset) => [text(asset.asset_id), asset]));
const maxJobs = Math.max(1, Number(request.provider_policy?.max_jobs || 120));
let jobCount = 0;

function addJob(job) {
  if (jobCount >= maxJobs) {
    hardBlockers.push('AUDIO_JOB_LIMIT_EXCEEDED');
    return '';
  }
  jobCount += 1;
  jobRegistry.push(job);
  return job.job_id;
}

const productions = list(brief.productions).map((canonical) => {
  const proposed = obj(proposedMap.get(text(canonical.production_id)));

  if (!canonical.audio_applicable) {
    return {
      production_id: canonical.production_id,
      content_mode: canonical.content_mode,
      total_duration_seconds: canonical.total_duration_seconds,
      audio_mode: 'NOT_APPLICABLE',
      voiceover: { enabled: false, segments: [], job_ids: [] },
      music: { enabled: false, source_strategy: 'none', job_ids: [] },
      sfx: { enabled: false, cues: [], job_ids: [] },
      captions: { enabled: false, segments: [], job_ids: [] },
      mix: { enabled: false, job_id: '', technical_targets: brief.technical_targets },
      scene_audio_map: [],
      dependencies: { visual_job_ids: [], audio_job_ids: [] },
      review_notes: []
    };
  }

  const proposedVoice = obj(proposed.voice_profile);
  let voiceMode = text(proposedVoice.mode, brief.voice_policy?.requested_mode).toLowerCase();
  if (!allowedVoiceModes.has(voiceMode)) {
    sanitizationLog.push({ path: `${canonical.production_id}.voice_profile.mode`, reasons: ['UNSUPPORTED_VOICE_MODE'] });
    voiceMode = canonical.voiceover_enabled ? 'generic_synthetic' : 'none';
  }

  const cloneRequested = ['custom_identity', 'cloned'].includes(voiceMode);
  if (cloneRequested && consentStatus !== 'GRANTED') {
    if (['custom_identity', 'cloned'].includes(text(brief.voice_policy?.requested_mode).toLowerCase())) {
      hardBlockers.push(`VOICE_CONSENT_REQUIRED:${canonical.production_id}`);
    } else {
      sanitizationLog.push({ path: `${canonical.production_id}.voice_profile.mode`, reasons: ['UNAUTHORIZED_VOICE_IDENTITY'] });
      voiceMode = 'generic_synthetic';
      reviewReasons.push(`Voz personalizada substituída por voz sintética genérica em ${canonical.production_id}.`);
    }
  }

  let speakingRate = clamp(
    proposedVoice.speaking_rate,
    Number(brief.voice_policy?.speaking_rate || 1),
    Number(brief.voice_policy?.allowed_rate_range?.[0] || 0.85),
    Number(brief.voice_policy?.allowed_rate_range?.[1] || 1.15)
  );

  const finalIdentityVoice = ['custom_identity', 'cloned'].includes(voiceMode);

  const voiceProfile = {
    enabled: canonical.voiceover_enabled,
    mode: canonical.voiceover_enabled ? voiceMode : 'none',
    language: text(proposedVoice.language, brief.locale),
    presentation: clean(proposedVoice.presentation || 'neutral'),
    delivery_style: clean(proposedVoice.delivery_style || 'warm, clear, confident and natural'),
    speaking_rate: speakingRate,
    voice_id: finalIdentityVoice ? text(brief.voice_policy?.voice_id) : '',
    consent_status: finalIdentityVoice ? consentStatus : 'NOT_REQUIRED',
    synthetic_voice_disclosed: canonical.voiceover_enabled && voiceMode === 'generic_synthetic',
    pronunciation_notes: unique(list(proposedVoice.pronunciation_notes).map(clean))
  };

  if (forbiddenImitation.test([
    voiceProfile.presentation,
    voiceProfile.delivery_style,
    ...voiceProfile.pronunciation_notes
  ].join(' '))) {
    sanitizationLog.push({ path: `${canonical.production_id}.voice_profile`, reasons: ['VOICE_IMITATION_REMOVED'] });
    voiceProfile.presentation = 'neutral';
    voiceProfile.delivery_style = 'warm, clear, confident and natural';
    voiceProfile.pronunciation_notes = [];
  }

  const treatmentMap = new Map(list(proposed.scene_treatments).map((entry) => [text(entry.scene_id), entry]));
  const voiceSegments = [];
  const sfxCues = [];
  const captionSegments = [];
  const sceneAudioMap = [];

  for (const scene of list(canonical.scenes)) {
    const treatment = obj(treatmentMap.get(text(scene.scene_id)));
    const delivery = obj(treatment.voice_delivery);
    const startPadding = clamp(delivery.pause_before_seconds, Number(brief.voice_policy?.lead_in_seconds || 0.18), 0, 1);
    const endPadding = clamp(delivery.pause_after_seconds, Number(brief.voice_policy?.lead_out_seconds || 0.18), 0, 1);
    const available = Math.max(0, Number(scene.duration_seconds) - startPadding - endPadding);
    const voiceEnabled = canonical.voiceover_enabled && Boolean(scene.voiceover_text);

    let estimated = estimateSpeechSeconds(scene.voiceover_text, speakingRate);
    if (voiceEnabled && estimated > available && available > 0) {
      const estimateAtOne = estimateSpeechSeconds(scene.voiceover_text, 1);
      const requiredRate = estimateAtOne / available;
      if (requiredRate <= Number(brief.voice_policy?.allowed_rate_range?.[1] || 1.15)) {
        speakingRate = Number(requiredRate.toFixed(2));
        voiceProfile.speaking_rate = Math.max(voiceProfile.speaking_rate, speakingRate);
        estimated = estimateSpeechSeconds(scene.voiceover_text, speakingRate);
        reviewReasons.push(`Velocidade ajustada dentro do limite para encaixar a locução em ${scene.scene_id}.`);
      } else {
        hardBlockers.push(`VOICEOVER_OVERFLOW:${scene.scene_id}`);
      }
    }

    let ttsJobId = '';
    if (voiceEnabled) {
      ttsJobId = addJob({
        job_id: stableId('AUD-TTS', [canonical.production_id, scene.scene_id, scene.voiceover_text]),
        job_type: 'TTS_VOICEOVER',
        provider_capability: 'text_to_speech',
        provider_resolution: 'DEFERRED_TO_CCG_80',
        production_id: canonical.production_id,
        scene_id: scene.scene_id,
        copy_ids: list(scene.voiceover_copy_ids),
        text: scene.voiceover_text,
        language: voiceProfile.language,
        voice_profile: voiceProfile,
        start_offset_seconds: startPadding,
        max_duration_seconds: available,
        estimated_duration_seconds: estimated,
        output: {
          format: 'wav',
          sample_rate_hz: brief.technical_targets.sample_rate_hz,
          bit_depth: brief.technical_targets.bit_depth,
          channels: 1
        },
        status: 'PLANNED',
        execute_in: 'CCG-80'
      });

      voiceSegments.push({
        segment_id: stableId('VOICE', [canonical.production_id, scene.scene_id]),
        scene_id: scene.scene_id,
        sequence: scene.sequence,
        copy_ids: list(scene.voiceover_copy_ids),
        text: scene.voiceover_text,
        start_offset_seconds: startPadding,
        max_duration_seconds: available,
        estimated_duration_seconds: estimated,
        speaking_rate: speakingRate,
        fit_status: estimated <= available + 0.05 ? 'FITS' : 'OVERFLOW',
        tts_job_id: ttsJobId
      });

      if (canonical.captions_enabled) {
        captionSegments.push({
          caption_id: stableId('CAP', [canonical.production_id, scene.scene_id]),
          scene_id: scene.scene_id,
          sequence: scene.sequence,
          text: scene.voiceover_text,
          start_offset_seconds: startPadding,
          end_offset_seconds: Math.min(
            Number(scene.duration_seconds) - endPadding,
            startPadding + estimated
          ),
          source: 'APPROVED_VOICEOVER_COPY'
        });
      }
    }

    const rawCues = list(treatment.sfx_cues);
    const canonicalCues = [];
    if (canonical.sfx_enabled) {
      for (const [index, cueValue] of rawCues.slice(0, 2).entries()) {
        const cue = obj(cueValue);
        let cueType = text(cue.cue_type, 'soft_transition').toLowerCase();
        if (!allowedCueTypes.has(cueType)) {
          sanitizationLog.push({ path: `${scene.scene_id}.sfx_cues.${index}.cue_type`, reasons: ['UNSUPPORTED_SFX_TYPE'] });
          cueType = 'soft_transition';
        }
        let description = clean(cue.description || 'subtle clean transition accent');
        if (restrictedAudio.test(description)) {
          sanitizationLog.push({ path: `${scene.scene_id}.sfx_cues.${index}.description`, reasons: ['RESTRICTED_SFX_REMOVED'] });
          description = 'subtle clean transition accent';
        }
        if (forbiddenImitation.test(description)) {
          sanitizationLog.push({ path: `${scene.scene_id}.sfx_cues.${index}.description`, reasons: ['IMITATION_REQUEST_REMOVED'] });
          description = 'original subtle transition accent';
        }
        const finalCue = {
          cue_id: stableId('SFX', [canonical.production_id, scene.scene_id, index + 1]),
          scene_id: scene.scene_id,
          cue_type: cueType,
          placement: ['scene_start', 'scene_end', 'mid_scene'].includes(text(cue.placement))
            ? text(cue.placement)
            : 'scene_start',
          relative_time_seconds: clamp(cue.relative_time_seconds, 0, 0, Number(scene.duration_seconds)),
          description,
          gain_db: clamp(cue.gain_db, -20, -36, -8)
        };
        canonicalCues.push(finalCue);
        sfxCues.push(finalCue);
      }
    }

    sceneAudioMap.push({
      scene_id: scene.scene_id,
      sequence: scene.sequence,
      duration_seconds: scene.duration_seconds,
      voice_segment_ids: voiceEnabled ? [stableId('VOICE', [canonical.production_id, scene.scene_id])] : [],
      sfx_cue_ids: canonicalCues.map((cue) => cue.cue_id),
      music_energy: clamp(treatment.music_energy, 0.45, 0, 1),
      music_action: clean(treatment.music_action || 'steady support'),
      intentional_silence: obj(treatment.intentional_silence),
      immutable: {
        scene_id: scene.scene_id,
        sequence: scene.sequence,
        duration_seconds: scene.duration_seconds
      }
    });
  }

  const proposedMusic = obj(proposed.music_direction);
  let sourceStrategy = text(proposedMusic.source_strategy).toLowerCase();
  if (!allowedSourceStrategies.has(sourceStrategy)) {
    sourceStrategy = canonical.music_enabled
      ? (list(brief.music_policy?.existing_usable_music_asset_ids).length ? 'reuse_licensed_asset' : 'generate_original')
      : 'none';
  }

  let selectedMusicAssetId = text(proposedMusic.selected_asset_id);
  if (sourceStrategy === 'reuse_licensed_asset' && !usableMusicIds.has(selectedMusicAssetId)) {
    const fallbackAsset = list(brief.music_policy?.existing_usable_music_asset_ids)[0] || '';
    if (fallbackAsset) {
      selectedMusicAssetId = fallbackAsset;
      reviewReasons.push(`Asset musical não autorizado foi substituído por ${fallbackAsset}.`);
    } else {
      sourceStrategy = 'generate_original';
      selectedMusicAssetId = '';
    }
  }

  const musicText = [
    ...list(proposedMusic.mood),
    ...list(proposedMusic.genre_family),
    ...list(proposedMusic.instrumentation),
    ...list(proposedMusic.originality_rules)
  ].join(' ');
  if (forbiddenImitation.test(musicText)) {
    sanitizationLog.push({ path: `${canonical.production_id}.music_direction`, reasons: ['ARTIST_IMITATION_REMOVED'] });
  }

  const music = {
    enabled: canonical.music_enabled,
    source_strategy: canonical.music_enabled ? sourceStrategy : 'none',
    selected_asset_id: canonical.music_enabled ? selectedMusicAssetId : '',
    mood: unique(
      list(proposedMusic.mood).length
        ? list(proposedMusic.mood).map(clean)
        : list(brief.music_policy?.moods)
    ),
    genre_family: unique(
      list(proposedMusic.genre_family).length
        ? list(proposedMusic.genre_family).map(clean)
        : list(brief.music_policy?.genre_family)
    ),
    bpm_target: canonical.music_enabled
      ? clamp(
          proposedMusic.bpm_target,
          Math.round(
