const defaultTransition = clamp(prefs.default_transition_seconds, 0.24, 0, 0.75);
const captionMargin = clamp(prefs.caption_safe_margin_seconds, 0.08, 0, 0.5);

function quantize(seconds) {
  return Math.max(0, Math.round(Number(seconds || 0) * fps));
}

function absoluteScenes(production) {
  if (!['SHORT_VIDEO', 'HYBRID'].includes(text(production.content_mode))) {
    return list(production.scenes).map((scene, index) => ({
      ...scene,
      canonical_start_seconds: 0,
      canonical_end_seconds: 0,
      canonical_start_frame: 0,
      canonical_end_frame: 1,
      canonical_duration_frames: 1,
      output_index: index + 1
    }));
  }

  let cumulative = 0;
  let previousEndFrame = 0;
  return list(production.scenes)
    .slice()
    .sort((a, b) => Number(a.sequence) - Number(b.sequence))
    .map((scene, index, all) => {
      cumulative += Number(scene.duration_seconds || 0);
      const endFrame = index === all.length - 1
        ? quantize(Number(production.total_duration_seconds || cumulative))
        : Math.max(previousEndFrame + 1, quantize(cumulative));
      const startFrame = previousEndFrame;
      previousEndFrame = endFrame;
      return {
        ...scene,
        canonical_start_seconds: Number((startFrame / fps).toFixed(6)),
        canonical_end_seconds: Number((endFrame / fps).toFixed(6)),
        canonical_start_frame: startFrame,
        canonical_end_frame: endFrame,
        canonical_duration_frames: endFrame - startFrame,
        output_index: index + 1
      };
