    variant_key: text(production.variant_key),
    concept_label: text(production.concept_label),
    content_mode: mode,
    timeline_type: timelineType,
    format: text(production.format),
    canvas: obj(production.canvas),
    source_duration_seconds: Number(production.total_duration_seconds || 0),
    duration_frames: ['SHORT_VIDEO', 'HYBRID'].includes(mode)
      ? quantize(Number(production.total_duration_seconds || 0))
      : scenes.length,
    duration_seconds: ['SHORT_VIDEO', 'HYBRID'].includes(mode)
      ? Number((quantize(Number(production.total_duration_seconds || 0)) / fps).toFixed(6))
      : 0,
    scenes,
    audio,
    allowed_scene_ids: scenes.map((scene) => text(scene.scene_id)),
    allowed_copy_ids: copyIds,
    dependencies: {
      visual_job_ids: visualDependencies,
      audio_job_ids: audioDependencies
    }
  };
});

const ccgOptionalSkip = productions.length > 0 && productions.every((production) => text(production.content_mode) === 'STATIC_SINGLE');

const brief = {
  brief_version: '1.0.0',
  run_id: text(data.ccg_context?.run_id),
  campaign_id: text(request.campaign_id),
  content_id: text(request.content_id),
  production_tier: text(request.production_tier, 'STANDARD'),
  timebase: {
    fps,
    frame_duration_seconds: Number(frameDuration.toFixed(9)),
    start_timecode: text(prefs.start_timecode, '00:00:00:00'),
    drop_frame: false,
    quantization_policy: 'ROUND_CUMULATIVE_BOUNDARIES',
    seconds_precision: 6
  },
  editorial_defaults: {
    default_transition_seconds: defaultTransition,
    caption_safe_margin_seconds: captionMargin,
    allowed_transition_types: ['none', 'cut', 'dissolve', 'fade', 'match_cut'],
    allowed_overlay_animations: ['none', 'fade', 'slide_up', 'scale_subtle'],
    minimum_overlay_duration_seconds: 0.6,
    maximum_transition_ratio: 0.12
  },
  productions,
  audio_job_registry: list(audioManifest.audio_job_registry),
  technical_targets: obj(audioManifest.technical_targets),
  render_policy: {
    provider_resolution: 'DEFERRED_TO_CCG_80',
    render_now: false,
    scene_ids_locked: true,
    sequence_locked: true,
    source_durations_locked: true,
    copy_text_locked: true,
    asset_bindings_locked: true,
    publication_forbidden: true
  },
  upstream_status: {
    scene_status: text(sceneManifest.status),
    audio_status: text(audioManifest.status),
    review_reasons: unique([
      ...list(sceneManifest.review?.reasons),
      ...list(audioManifest.review?.reasons)
    ])
  },
  prepared_at: new Date().toISOString()
};

return [{
  json: {
    ...data,
    ccg_optional_modules: {
      ...(data.ccg_optional_modules || {}),
      CCG_70: ccgOptionalSkip
        ? { status: 'SKIPPED_NOT_REQUIRED', reason_code: 'CONTENT_MODE_NOT_APPLICABLE', module: 'CCG-70' }
        : { status: 'REQUIRED', module: 'CCG-70' }
    },
    timeline_planning_brief: brief,
    ccg70_preparation: {
      productions: productions.length,
      video_productions: productions.filter((production) => production.timeline_type === 'TEMPORAL_VIDEO').length,
      carousel_productions: productions.filter((production) => production.timeline_type === 'FRAME_SEQUENCE').length,
      still_productions: productions.filter((production) => production.timeline_type === 'STILL_FRAME').length,
      scenes: productions.reduce((sum, production) => sum + production.scenes.length, 0),
      fps,
      prepared_at: brief.prepared_at
    }
  },
  binary: item.binary
}];

const item = $input.first();
const data = item.json || {};
const brief = data.timeline_planning_brief || {};

const text = (value, fallback = '') => value === undefined || value === null ? fallback : String(value).trim();
const list = (value) => Array.isArray(value) ? value : [];
const clamp = (value, fallback, min, max) => {
  const number = Number(value);
  return Number.isFinite(number) ? Math.max(min, Math.min(max, number)) : fallback;
};

function transitionDuration(scene, adjacentDuration) {
  const type = text(scene.transition_out);
  if (['none', 'cut', 'match_cut'].includes(type)) return 0;
  const maxByScene = Math.max(0, Math.min(
    Number(scene.duration_seconds || 0),
    Number(adjacentDuration || 0)
  ) * Number(brief.editorial_defaults.maximum_transition_ratio || 0.12));
  return Number(Math.min(
    Number(brief.editorial_defaults.default_transition_seconds || 0.24),
    maxByScene || Number(brief.editorial_defaults.default_transition_seconds || 0.24)
  ).toFixed(3));
}

function overlayCue(scene, layer) {
  if (scene.content_mode !== 'SHORT_VIDEO') {
    return {
      copy_id: layer.copy_id,
      start_offset_seconds: 0,
      end_offset_seconds: 0,
      animation_in: 'none',
      animation_out: 'none'
    };
  }

  const duration = Number(scene.duration_seconds || 0);
  const role = text(layer.role).toLowerCase();
  let start = 0.12;
  let end = Math.max(start + 0.6, duration - 0.12);

  if (role === 'cta') {
    start = Math.max(0.1, duration * 0.18);
  } else if (role === 'disclaimer') {
    start = Math.max(0.1, duration * 0.45);
  } else if (role === 'body') {
    start = Math.max(0.1, duration * 0.12);
  }

  return {
    copy_id: layer.copy_id,
    start_offset_seconds: Number(start.toFixed(3)),
    end_offset_seconds: Number(Math.min(duration, end).toFixed(3)),
    animation_in: 'fade',
    animation_out: 'fade'
  };
}

const productions = list(brief.productions).map((production) => {
  const edits = list(production.scenes).map((scene, index, scenes) => {
    const next = scenes[index + 1];
    return {
      scene_id: scene.scene_id,
      transition_in_duration_seconds: 0,
      transition_out_duration_seconds: production.timeline_type === 'TEMPORAL_VIDEO'
        ? transitionDuration(scene, next?.duration_seconds)
        : 0,
      overlay_cues: list(scene.copy_layers)
        .filter((layer) => text(layer.role).toLowerCase() !== 'voiceover')
        .map((layer) => overlayCue(scene, layer)),
      music_cue: {
        action: text(
          production.audio?.scene_audio_map?.find?.((entry) => entry.scene_id === scene.scene_id)?.music_action,
          scene.role === 'hook' ? 'gentle entrance' : scene.role === 'cta' ? 'soft resolution' : 'steady support'
        ),
        energy: clamp(
          production.audio?.scene_audio_map?.find?.((entry) => entry.scene_id === scene.scene_id)?.music_energy,
          scene.role === 'hook' ? 0.58 : scene.role === 'cta' ? 0.45 : 0.52,
          0,
          1
        )
      },
      pacing_note: production.timeline_type === 'TEMPORAL_VIDEO'
        ? (scene.role === 'hook' ? 'leitura imediata no primeiro segundo' : 'ritmo estável e legível')
        : 'quadro independente',
      review_notes: []
    };
  });

  return {
    production_id: production.production_id,
    pacing_style: production.timeline_type === 'TEMPORAL_VIDEO'
      ? 'clean_social_performance'
      : 'ordered_static_composition',
    scene_edits: edits,
    review_notes: []
  };
});

return [{
  json: {
    ...data,
    timeline_edit_proposal: {
      proposal_version: '1.0.0',
      productions,
      review: { required: false, reasons: [] }
    },
    ccg70_generation_mode: 'DETERMINISTIC_DRY_RUN'
  },
  binary: item.binary
}];

parameters.text:
=Crie a proposta editorial e retorne SOMENTE o JSON exigido pelo parser.

Timeline planning brief fechado:
{{ JSON.stringify($json.timeline_planning_brief) }}

parameters.jsCode:
const incomingItem = $input.first();
const incoming = incomingItem.json || {};
let preparedItem = incomingItem;
try { preparedItem = $('CCG-70 Prepare Timeline Planning Brief').first(); } catch {}

const base = preparedItem.json || incoming;
const request = base.production_request || {};
const brief = base.timeline_planning_brief || {};

const text = (value, fallback = '') => value === undefined || value === null ? fallback : String(value).trim();
const list = (value) => Array.isArray(value) ? value : [];
const obj = (value) => value && typeof value === 'object' && !Array.isArray(value) ? value : {};
const unique = (values) => [...new Set(values.map((value) => text(value)).filter(Boolean))];
const clamp = (value, fallback, min, max) => {
  const number = Number(value);
  return Number.isFinite(number) ? Math.max(min, Math.min(max, number)) : fallback;
};

function unwrap(value) {
  if (value?.timeline_edit_proposal) return value;
  if (value?.output && typeof value.output === 'object') return value.output;
  for (const candidate of [value?.text, value?.output]) {
    if (typeof candidate === 'string') {
      try { return JSON.parse(candidate); } catch {}
    }
  }
  return value || {};
}

function stableId(prefix, values) {
  const source = values.map((value) => text(value)).join('|');
  let hash = 2166136261;
  for (let index = 0; index < source.length; index++) {
    hash ^= source.charCodeAt(index);
    hash = Math.imul(hash, 16777619);
  }
  return `${prefix}-${(hash >>> 0).toString(16).padStart(8, '0')}`;
}

function clean(value) {
  return text(value)
    .replace(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi, '[EMAIL_REDACTED]')
    .replace(/(?:\+?55\s*)?(?:\(?\d{2}\)?\s*)?(?:9?\d{4})[-.\s]?\d{4}/g, '[PHONE_REDACTED]')
    .replace(/\b\d{3}\.?\d{3}\.?\d{3}-?\d{2}\b/g, '[CPF_REDACTED]');
}

const fps = Number(brief.timebase?.fps || 30);
const toFrame = (seconds) => Math.max(0, Math.round(Number(seconds || 0) * fps));
const fromFrame = (frame) => Number((Number(frame || 0) / fps).toFixed(6));
const allowedTransitions = new Set(list(brief.editorial_defaults?.allowed_transition_types));
const allowedAnimations = new Set(list(brief.editorial_defaults?.allowed_overlay_animations));
const audioJobIds = new Set(list(brief.audio_job_registry).map((job) => text(job.job_id)));
const audioJobMap = new Map(list(brief.audio_job_registry).map((job) => [text(job.job_id), job]));

const parsed = unwrap(incoming);
const proposal = obj(parsed.timeline_edit_proposal || incoming.timeline_edit_proposal);
const proposedProductions = new Map(list(proposal.productions).map((production) => [text(production.production_id), production]));
const reviewReasons = [
  ...list(base.ccg70_input_validation?.warnings),
  ...list(brief.upstream_status?.review_reasons),
  ...list(proposal.review?.reasons)
];
const hardBlockers = [];
const sanitizationLog = [];
const jobs = [];

function sanitizeTransition(type, duration, sceneDuration, adjacentDuration, path) {
  let finalType = text(type, 'none').toLowerCase();
  if (!allowedTransitions.has(finalType)) {
    sanitizationLog.push({ path, reasons: ['UNSUPPORTED_TRANSITION_TYPE'] });
    finalType = 'cut';
  }
  if (['none', 'cut', 'match_cut'].includes(finalType)) return { type: finalType, duration_seconds: 0 };

  const ratio = Number(brief.editorial_defaults?.maximum_transition_ratio || 0.12);
  const maxDuration = Math.max(0, Math.min(
    Number(sceneDuration || 0),
    Number(adjacentDuration || sceneDuration || 0)
  ) * ratio);
  const finalDuration = clamp(
    duration,
    Number(brief.editorial_defaults?.default_transition_seconds || 0.24),
    0,
    Math.min(0.75, maxDuration || 0.24)
  );
  if (Number(duration) !== finalDuration) {
    sanitizationLog.push({ path, reasons: ['TRANSITION_DURATION_CLAMPED'] });
  }
  return { type: finalType, duration_seconds: Number(finalDuration.toFixed(3)) };
}

function animation(value, path) {
  const candidate = text(value, 'none').toLowerCase();
  if (allowedAnimations.has(candidate)) return candidate;
  sanitizationLog.push({ path, reasons: ['UNSUPPORTED_OVERLAY_ANIMATION'] });
  return 'fade';
}

function track(id, type, order, muted = false) {
  return {
    track_id: id,
    track_type: type,
    order,
    muted,
    locked: true
  };
}

const productionTimelines = list(brief.productions).map((canonical) => {
  const proposed = obj(proposedProductions.get(text(canonical.production_id)));
  const editMap = new Map(list(proposed.scene_edits).map((edit) => [text(edit.scene_id), edit]));
  const tracks = [];
  const clips = [];
  const transitions = [];
  const markers = [];
  const outputItems = [];

  if (canonical.timeline_type === 'TEMPORAL_VIDEO') {
    tracks.push(
      track(`${canonical.production_id}:track:visual`, 'VIDEO_BASE', 10),
      track(`${canonical.production_id}:track:overlay`, 'GRAPHIC_OVERLAY', 20),
      track(`${canonical.production_id}:track:caption`, 'CAPTIONS', 30),
      track(`${canonical.production_id}:track:voice`, 'VOICEOVER', 40),
      track(`${canonical.production_id}:track:music`, 'MUSIC', 50),
      track(`${canonical.production_id}:track:sfx`, 'SFX', 60)
    );
  } else {
    tracks.push(
      track(`${canonical.production_id}:track:visual`, 'STILL_BASE', 10),
      track(`${canonical.production_id}:track:overlay`, 'GRAPHIC_OVERLAY', 20)
    );
  }

  const sceneMap = new Map(list(canonical.scenes).map((scene) => [text(scene.scene_id), scene]));
  for (const proposedEdit of list(proposed.scene_edits)) {
    const proposedSceneId = text(proposedEdit.scene_id);
    const canonicalScene = sceneMap.get(proposedSceneId);
    if (!canonicalScene) {
      sanitizationLog.push({
        path: `${canonical.production_id}.scene_edits.${proposedSceneId}`,
        reasons: ['UNKNOWN_SCENE_EDIT_IGNORED']
      });
      continue;
    }
    const allowedSceneCopyIds = new Set(list(canonicalScene.copy_ids).map(text));
    for (const cue of list(proposedEdit.overlay_cues)) {
      if (!allowedSceneCopyIds.has(text(cue.copy_id))) {
        sanitizationLog.push({
          path: `${canonical.production_id}.${proposedSceneId}.overlay_cues.${text(cue.copy_id)}`,
          reasons: ['UNKNOWN_COPY_CUE_IGNORED']
        });
      }
    }
  }
  const visualDeps = unique(list(canonical.dependencies?.visual_job_ids));
  const audioDeps = unique(list(canonical.dependencies?.audio_job_ids));

  for (const [index, scene] of list(canonical.scenes).entries()) {
    const edit = obj(editMap.get(text(scene.scene_id)));
    const nextScene = canonical.scenes[index + 1];
    const sceneStartFrame = Number(scene.canonical_start_frame || 0);
    const sceneEndFrame = Number(scene.canonical_end_frame || 1);
    const sceneStart = Number(scene.canonical_start_seconds || 0);
    const sceneEnd = Number(scene.canonical_end_seconds || 0);

    if (!text(scene.composition_job_id)) {
      hardBlockers.push(`MISSING_COMPOSITION_JOB:${scene.scene_id}`);
    }

    const visualClipId = stableId('TL-VIS', [canonical.production_id, scene.scene_id]);
    clips.push({
      clip_id: visualClipId,
      track_id: `${canonical.production_id}:track:visual`,
      clip_type: canonical.timeline_type === 'TEMPORAL_VIDEO' ? 'VIDEO_SCENE' : 'STILL_FRAME',
      scene_id: scene.scene_id,
      sequence: scene.sequence,
      source: {
        composition_job_id: text(scene.composition_job_id),
        asset_bindings: obj(scene.asset_bindings)
      },
      start_frame: sceneStartFrame,
      end_frame: sceneEndFrame,
      start_seconds: sceneStart,
      end_seconds: sceneEnd,
      duration_frames: Math.max(1, sceneEndFrame - sceneStartFrame),
      duration_seconds: canonical.timeline_type === 'TEMPORAL_VIDEO'
        ? Number((sceneEnd - sceneStart).toFixed(6))
        : 0,
      in_frame: 0,
      out_frame: Math.max(1, sceneEndFrame - sceneStartFrame),
      z_index: 0,
      dependencies: unique([
        ...list(scene.dependencies?.retrieval_job_ids),
        ...list(scene.dependencies?.generation_job_ids),
        text(scene.composition_job_id)
      ]),
      immutable: true
    });

    markers.push({
      marker_id: stableId('MARK', [canonical.production_id, scene.scene_id, 'start']),
      marker_type: 'SCENE_START',
      scene_id: scene.scene_id,
      frame: sceneStartFrame,
      seconds: sceneStart,
      label: `${scene.sequence}. ${text(scene.role)}`
    });

    if (canonical.timeline_type !== 'TEMPORAL_VIDEO') {
      outputItems.push({
        output_index: Number(scene.output_index || scene.sequence),
        scene_id: scene.scene_id,
        visual_clip_id: visualClipId,
        file_stem: `${canonical.deliverable_id}-${String(scene.sequence).padStart(2, '0')}`
      });
    }

    const proposedCues = new Map(list(edit.overlay_cues).map((cue) => [text(cue.copy_id), cue]));
    for (const [layerIndex, layer] of list(scene.copy_layers).entries()) {
      if (text(layer.role).toLowerCase() === 'voiceover') continue;

      const cue = obj(proposedCues.get(text(layer.copy_id)));
      let startOffset = canonical.timeline_type === 'TEMPORAL_VIDEO'
        ? clamp(cue.start_offset_seconds, 0.12, 0, Math.max(0, Number(scene.duration_seconds) - 0.1))
        : 0;
      let endOffset = canonical.timeline_type === 'TEMPORAL_VIDEO'
        ? clamp(cue.end_offset_seconds, Math.max(startOffset + 0.6, Number(scene.duration_seconds) - 0.12), startOffset, Number(scene.duration_seconds))
        : 0;

      const minDuration = Number(brief.editorial_defaults?.minimum_overlay_duration_seconds || 0.6);
      if (canonical.timeline_type === 'TEMPORAL_VIDEO' && endOffset - startOffset < minDuration) {
        endOffset = Math.min(Number(scene.duration_seconds), startOffset + minDuration);
        if (endOffset - startOffset < minDuration - 0.01) {
          reviewReasons.push(`Overlay curto em ${scene.scene_id}/${layer.copy_id}.`);
        }
      }

      const startFrame = canonical.timeline_type === 'TEMPORAL_VIDEO'
        ? Math.max(sceneStartFrame, sceneStartFrame + toFrame(startOffset))
        : 0;
      const endFrame = canonical.timeline_type === 'TEMPORAL_VIDEO'
        ? Math.min(sceneEndFrame, sceneStartFrame + toFrame(endOffset))
        : 1;

      clips.push({
        clip_id: stableId('TL-OVR', [canonical.production_id, scene.scene_id, layer.copy_id]),
        track_id: `${canonical.production_id}:track:overlay`,
        clip_type: 'TEXT_OVERLAY',
        scene_id: scene.scene_id,
        copy_id: text(layer.copy_id),
        text: text(layer.text),
        role: text(layer.role),
        path: text(layer.path),
        zone_id: text(layer.zone_id),
        alignment: text(layer.alignment, 'left'),
        max_lines: Number(layer.max_lines || 3),
        fit_policy: text(layer.fit_policy, 'shrink_within_limits_never_rewrite'),
        start_frame: startFrame,
        end_frame: Math.max(startFrame + 1, endFrame),
        start_seconds: fromFrame(startFrame),
        end_seconds: fromFrame(Math.max(startFrame + 1, endFrame)),
        animation_in: canonical.timeline_type === 'TEMPORAL_VIDEO'
          ? animation(cue.animation_in, `${scene.scene_id}.${layer.copy_id}.animation_in`)
          : 'none',
        animation_out: canonical.timeline_type === 'TEMPORAL_VIDEO'
          ? animation(cue.animation_out, `${scene.scene_id}.${layer.copy_id}.animation_out`)
          : 'none',
        z_index: 100 + layerIndex,
        dependencies: [text(scene.composition_job_id)],
        immutable_text: true
      });
    }

    if (canonical.timeline_type === 'TEMPORAL_VIDEO') {
      const transitionOut = sanitizeTransition(
        scene.transition_out,
        edit.transition_out_duration_seconds,
        scene.duration_seconds,
        nextScene?.duration_seconds,
        `${scene.scene_id}.transition_out`
      );
      transitions.push({
        transition_id: stableId('TRN', [canonical.production_id, scene.scene_id, 'out']),
        from_scene_id: scene.scene_id,
        to_scene_id: nextScene ? nextScene.scene_id : '',
        boundary_frame: sceneEndFrame,
        boundary_seconds: sceneEnd,
        type: nextScene ? transitionOut.type : 'none',
        duration_seconds: nextScene ? transitionOut.duration_seconds : 0,
        duration_frames: nextScene ? toFrame(transitionOut.duration_seconds) : 0
      });
    }
  }

  const audio = obj(canonical.audio);
  const sceneLookup = new Map(list(canonical.scenes).map((scene) => [text(scene.scene_id), scene]));

  if (canonical.timeline_type === 'TEMPORAL_VIDEO') {
    for (const segment of list(audio.voiceover?.segments)) {
      const scene = sceneLookup.get(text(segment.scene_id));
      if (!scene) {
        hardBlockers.push(`UNKNOWN_VOICE_SCENE:${text(segment.scene_id)}`);
        continue;
      }
      if (!audioJobIds.has(text(segment.tts_job_id))) {
        hardBlockers.push(`UNKNOWN_TTS_JOB:${text(segment.tts_job_id)}`);
        continue;
      }

      const startSeconds = Number(scene.canonical_start_seconds) + Number(segment.start_offset_seconds || 0);
      const unclampedEnd = startSeconds + Number(segment.estimated_duration_seconds || 0);
      const endSeconds = Math.min(Number(scene.canonical_end_seconds), unclampedEnd);
      const startFrame = Math.max(Number(scene.canonical_start_frame), toFrame(startSeconds));
      const endFrame = Math.min(Number(scene.canonical_end_frame), Math.max(startFrame + 1, toFrame(endSeconds)));

      clips.push({
        clip_id: stableId('TL-VO', [canonical.production_id, segment.segment_id]),
        track_id: `${canonical.production_id}:track:voice`,
        clip_type: 'VOICEOVER_AUDIO',
        scene_id: segment.scene_id,
        segment_id: segment.segment_id,
        copy_ids: list(segment.copy_ids),
        source_job_id: text(segment.tts_job_id),
        start_frame: startFrame,
        end_frame: endFrame,
        start_seconds: fromFrame(startFrame),
        end_seconds: fromFrame(endFrame),
        gain_db: 0,
        pan: 0,
        dependencies: [text(segment.tts_job_id)],
        immutable_text: true
      });
    }

    const musicJobId = list(audio.music?.job_ids)[0] || '';
    if (audio.music?.enabled) {
      if (musicJobId && !audioJobIds.has(text(musicJobId))) {
        hardBlockers.push(`UNKNOWN_MUSIC_JOB:${musicJobId}`);
      }
      clips.push({
        clip_id: stableId('TL-MUS', [canonical.production_id, musicJobId || audio.music?.selected_asset_id]),
        track_id: `${canonical.production_id}:track:music`,
        clip_type: 'MUSIC_BED',
        source_job_id: text(musicJobId),
        source_asset_id: text(audio.music?.selected_asset_id),
        start_frame: 0,
        end_frame: Number(canonical.duration_frames),
        start_seconds: 0,
        end_seconds: Number(canonical.duration_seconds),
        gain_db: -14,
        ducking: {
          enabled: Boolean(audio.voiceover?.enabled),
          amount_db: Number(brief.technical_targets?.speech_priority_ducking_db || -8),
          trigger_track_id: `${canonical.production_id}:track:voice`
        },
        dependencies: unique([musicJobId]),
        original_only: true
      });
    }

    for (const cue of list(audio.sfx?.cues)) {
      const scene = sceneLookup.get(text(cue.scene_id));
      if (!scene) {
        hardBlockers.push(`UNKNOWN_SFX_SCENE:${text(cue.scene_id)}`);
        continue;
      }
      const sfxJob = list(audio.sfx?.job_ids).map((id) => audioJobMap.get(text(id)))
        .find((job) => text(job?.scene_id) === text(cue.scene_id)) ||
        audioJobMap.get(text(list(audio.sfx?.job_ids)[0]));
      const sourceJobId = text(sfxJob?.job_id);
      if (!sourceJobId || !audioJobIds.has(sourceJobId)) {
        hardBlockers.push(`UNKNOWN_SFX_JOB:${text(cue.cue_id)}`);
        continue;
      }
      const startSeconds = Number(scene.canonical_start_seconds) + Number(cue.relative_time_seconds || 0);
      const startFrame = Math.max(Number(scene.canonical_start_frame), toFrame(startSeconds));
      const durationFrames = Math.max(1, Math.round(fps * 0.4));
      clips.push({
        clip_id: stableId('TL-SFX', [canonical.production_id, cue.cue_id]),
        track_id: `${canonical.production_id}:track:sfx`,
        clip_type: 'SFX_AUDIO',
        scene_id: cue.scene_id,
        cue_id: cue.cue_id,
        source_job_id: sourceJobId,
