    display_name: text(provider.display_name || provider.name, providerId),
    enabled: provider.enabled !== false,
    allowed,
    priority: Number.isFinite(Number(provider.priority)) ? Number(provider.priority) : index + 1,
    capabilities,
    models: list(provider.models).map((modelValue) => {
      const model = obj(modelValue);
      return {
        model_id: text(model.model_id || model.id || model.name),
        capabilities: unique(
          list(model.capabilities).length
            ? list(model.capabilities).map((capability) => text(capability).toLowerCase())
            : capabilities
        ),
        enabled: model.enabled !== false,
        quality_tier: text(model.quality_tier),
        cost_profile: obj(model.cost_profile)
      };
    }),
    cost_profile: obj(provider.cost_profile),
    max_concurrency: clampInt(provider.max_concurrency, defaults.concurrency, 1, 50),
    adapter_workflow_id: text(provider.adapter_workflow_id),
    credential_ref_name: text(provider.credential_ref_name),
    region: text(provider.region),
    notes: unique(list(provider.notes))
  };
});

const maxJobsRaw = request.provider_policy?.max_jobs ?? request.production_execution?.max_jobs ?? data.module_outputs?.CCG_00?.intake_manifest?.limits?.max_jobs ?? 120;
const maximumJobs = Math.max(1, Number.isFinite(Number(maxJobsRaw)) ? Number(maxJobsRaw) : 120);
const maxRevisionsRaw = request.provider_policy?.max_revisions ?? request.production_execution?.max_revisions ?? data.module_outputs?.CCG_00?.intake_manifest?.limits?.max_revisions ?? 0;
const maximumRevisions = Math.max(0, Number.isFinite(Number(maxRevisionsRaw)) ? Number(maxRevisionsRaw) : 0);
const maximumCostRaw = request.provider_policy?.max_cost ?? request.production_execution?.max_cost ?? request.budget?.max_cost ?? data.module_outputs?.CCG_00?.intake_manifest?.limits?.max_cost;
const maximumCostConfigured = maximumCostRaw !== undefined && maximumCostRaw !== null && maximumCostRaw !== '' && Number.isFinite(Number(maximumCostRaw));
const maximumCost = maximumCostConfigured ? Math.max(0, Number(maximumCostRaw)) : null;

const brief = {const brief = {
  brief_version: '1.0.0',
  run_id: text(data.ccg_context?.run_id),
  campaign_id: text(request.campaign_id),
  content_id: text(request.content_id),
  production_id: text(request.production_id),
  production_tier: tier,
  mode: text(data.ccg_context?.mode),
  jobs,
  provider_catalog: providerCatalog,
  allowed_provider_ids: [...allowedProviders],
  execution_policy: {
    allowed_providers: [...allowedProviders],
    max_jobs: maximumJobs,
    max_revisions: maximumRevisions,
    max_cost: maximumCost,
    max_cost_configured: maximumCostConfigured,
    dispatch_requested: execution.dispatch_enabled === true && text(data.ccg_context?.mode) === 'LIVE',
    adapter_orchestrator_workflow_id: text(execution.adapter_orchestrator_workflow_id),
    require_known_cost_before_dispatch: execution.require_known_cost_before_dispatch !== false,
    require_credentials_before_dispatch: execution.require_credentials_before_dispatch !== false,
    require_adapter_before_dispatch: execution.require_adapter_before_dispatch !== false,
    require_human_approval: request.provider_policy?.require_human_approval !== false,
    maximum_jobs: maximumJobs,
    maximum_cost: maximumCost,
    currency: text(request.budget?.currency, 'USD'),
    default_max_attempts: defaults.max_attempts,
    default_concurrency: defaults.concurrency,
    default_fallback_count: defaults.fallback_count,
    default_timeout_seconds: defaults.timeout_seconds,
    no_publish: true
  },
  existing_manifests: {
    asset_manifest_status: text(assetManifest.status),
    audio_manifest_status: text(audioManifest.status),
    timeline_status: text(timeline.status)
  },
  prepared_at: new Date().toISOString()
};

return [{
  json: {
    ...data,
    production_planning_brief: brief,
    ccg80_preparation: {
      jobs: jobs.length,
      providers: providerCatalog.length,
      capabilities: unique(jobs.map((job) => job.provider_capability)),
      maximum_jobs: maximumJobs,
      maximum_cost: maximumCost,
      dispatch_requested: brief.execution_policy.dispatch_requested,
      prepared_at: brief.prepared_at
    }
  },
  binary: item.binary
}];

const item = $input.first();
const data = item.json || {};
const brief = data.production_planning_brief || {};

const text = (value, fallback = '') => value === undefined || value === null ? fallback : String(value).trim();
const list = (value) => Array.isArray(value) ? value : [];
const unique = (values) => [...new Set(values.map((value) => text(value)).filter(Boolean))];

const jobPlans = list(brief.jobs).map((job, index) => ({
  job_id: job.job_id,
  selected_provider_id: 'mock',
  selected_model_id: `mock-${job.provider_capability}-v1`,
  fallback_provider_ids: [],
  max_attempts: 1,
  timeout_seconds: 30,
  concurrency_group: job.provider_capability,
  priority: Number(job.priority || index + 1),
  estimated_cost: 0,
  cost_known: true,
  currency: brief.execution_policy?.currency || 'USD',
  dispatch_mode: 'DRY_RUN_SIMULATION',
  rationale: 'Dry-run determinístico: nenhum provedor externo será chamado.'
}));

return [{
  json: {
    ...data,
    production_plan_proposal: {
      proposal_version: '1.0.0',
      job_plans: jobPlans,
      execution_notes: [
        'Nenhum job será despachado.',
        'Todos os custos são simulados como zero.',
        'Dependências e estágios serão validados pelo guardrail determinístico.'
      ],
      review: {
        required: false,
        reasons: []
      }
    },
    ccg80_generation_mode: 'DETERMINISTIC_DRY_RUN'
  },
  binary: item.binary
}];

parameters.text:
=Crie a proposta de roteamento de produção e retorne SOMENTE o JSON exigido pelo parser.

Production planning brief fechado:
{{ JSON.stringify($json.production_planning_brief) }}

parameters.jsCode:
const incomingItem = $input.first();
const incoming = incomingItem.json || {};

let preparedItem = incomingItem;
try {
  preparedItem = $('CCG-80 Prepare Production Planning Brief').first();
} catch {}

const base = preparedItem.json || incoming;
const request = base.production_request || {};
const brief = base.production_planning_brief || {};

const text = (value, fallback = '') => value === undefined || value === null ? fallback : String(value).trim();
const list = (value) => Array.isArray(value) ? value : [];
const obj = (value) => value && typeof value === 'object' && !Array.isArray(value) ? value : {};
const unique = (values) => [...new Set(values.map((value) => text(value)).filter(Boolean))];
const clampInt = (value, fallback, min, max) => {
  const number = Number(value);
  return Number.isFinite(number) ? Math.max(min, Math.min(max, Math.floor(number))) : fallback;
};
const clampNumber = (value, fallback, min, max) => {
  const number = Number(value);
  return Number.isFinite(number) ? Math.max(min, Math.min(max, number)) : fallback;
};

function unwrap(value) {
  if (value?.production_plan_proposal) return value;
  if (value?.output && typeof value.output === 'object') return value.output;
  for (const candidate of [value?.text, value?.output]) {
    if (typeof candidate === 'string') {
      try { return JSON.parse(candidate); } catch {}
    }
  }
  return value || {};
}

function stableId(prefix, values) {
  const source = values.map((value) => text(value)).join('|');
  let hash = 2166136261;
  for (let index = 0; index < source.length; index++) {
    hash ^= source.charCodeAt(index);
    hash = Math.imul(hash, 16777619);
  }
  return `${prefix}-${(hash >>> 0).toString(16).padStart(8, '0')}`;
}

function costFromProfile(profileValue, job) {
  const profile = obj(profileValue);
  const type = text(profile.type).toLowerCase();

  if (type === 'per_job' && Number.isFinite(Number(profile.amount))) {
    return {
      known: true,
      amount: Math.max(0, Number(profile.amount)),
      rule: 'per_job'
    };
  }

  if (type === 'fixed_by_capability') {
    const amount = Number(obj(profile.amounts)[job.provider_capability]);
    if (Number.isFinite(amount)) {
      return {
        known: true,
        amount: Math.max(0, amount),
        rule: 'fixed_by_capability'
      };
    }
  }

  if (type === 'per_second') {
    const seconds = Number(
      job.output_spec?.duration_seconds ??
      job.raw_job?.duration_seconds ??
      job.raw_job?.output_spec?.duration_seconds ??
      0
    );
    const rate = Number(profile.amount_per_second);
    if (Number.isFinite(seconds) && seconds >= 0 && Number.isFinite(rate)) {
      return {
        known: true,
        amount: Math.max(0, seconds * rate),
        rule: 'per_second'
      };
    }
  }

  if (type === 'per_unit') {
    const units = Number(profile.default_units);
    const amount = Number(profile.amount_per_unit);
    if (Number.isFinite(units) && Number.isFinite(amount)) {
      return {
        known: true,
        amount: Math.max(0, units * amount),
        rule: 'per_unit'
      };
    }
  }

  return {
    known: false,
    amount: 0,
    rule: 'unresolved'
  };
}

function eligibleProviders(capability) {
  return list(brief.provider_catalog)
    .filter((provider) => {
      return (
        provider.enabled === true &&
        provider.allowed === true &&
        list(provider.capabilities).includes(capability)
      );
    })
    .sort((a, b) => Number(a.priority || 999) - Number(b.priority || 999));
}

function selectedModel(provider, capability, proposedModelId) {
  const models = list(provider?.models).filter((model) => {
    return (
      model.enabled !== false &&
      (!list(model.capabilities).length || list(model.capabilities).includes(capability))
    );
  });

  const proposed = models.find((model) => text(model.model_id) === proposedModelId);
  return proposed || models[0] || null;
}

function topologicalStages(jobs) {
  const ids = new Set(jobs.map((job) => job.job_id));
  const indegree = new Map();
  const outgoing = new Map();

  for (const job of jobs) {
    indegree.set(job.job_id, 0);
    outgoing.set(job.job_id, []);
  }

  const missing = [];
  for (const job of jobs) {
    for (const dependency of list(job.dependencies)) {
      if (!ids.has(dependency)) {
        missing.push({ job_id: job.job_id, dependency_id: dependency });
        continue;
      }
      indegree.set(job.job_id, Number(indegree.get(job.job_id)) + 1);
      outgoing.get(dependency).push(job.job_id);
    }
  }

  const stages = [];
  let frontier = jobs
    .filter((job) => indegree.get(job.job_id) === 0)
    .map((job) => job.job_id)
    .sort();

  const visited = [];
  while (frontier.length) {
    stages.push(frontier);
    const next = [];
    for (const jobId of frontier) {
      visited.push(jobId);
      for (const dependent of outgoing.get(jobId)) {
        indegree.set(dependent, Number(indegree.get(dependent)) - 1);
        if (indegree.get(dependent) === 0) next.push(dependent);
      }
    }
    frontier = unique(next).sort();
  }

  const cycleIds = jobs
    .map((job) => job.job_id)
    .filter((jobId) => !visited.includes(jobId));

  return { stages, missing, cycle_ids: cycleIds };
}

const parsed = unwrap(incoming);
const proposal = obj(parsed.production_plan_proposal || incoming.production_plan_proposal);
const proposedPlanMap = new Map(
  list(proposal.job_plans).map((plan) => [text(plan.job_id), plan])
);

const mode = text(brief.mode);
const dryRun = mode === 'DRY_RUN';
const reviewReasons = [
  ...list(base.ccg80_input_validation?.warnings),
  ...list(proposal.review?.reasons)
];
const hardBlockers = [];
const sanitizationLog = [];
const resolvedJobs = [];
const providerMap = new Map(
  list(brief.provider_catalog).map((provider) => [text(provider.provider_id), provider])
);

const knownJobIds = new Set(list(brief.jobs).map((job) => text(job.job_id)));

for (const proposedPlan of list(proposal.job_plans)) {
  if (!knownJobIds.has(text(proposedPlan.job_id))) {
    sanitizationLog.push({
      path: `production_plan_proposal.job_plans.${text(proposedPlan.job_id)}`,
      reasons: ['UNKNOWN_JOB_IGNORED']
    });
  }
}

for (const job of list(brief.jobs)) {
  const proposed = obj(proposedPlanMap.get(job.job_id));
  const capability = text(job.provider_capability).toLowerCase();

  let selectedProvider;
  let selectedModelValue = null;
  let fallbackProviders = [];
  let cost = { known: false, amount: 0, rule: 'unresolved' };

  if (dryRun) {
    selectedProvider = {
      provider_id: 'mock',
      display_name: 'Mock deterministic provider',
      priority: 0,
      capabilities: [capability],
      max_concurrency: Number(brief.execution_policy?.default_concurrency || 1),
      adapter_workflow_id: '',
      credential_ref_name: '',
      cost_profile: { type: 'per_job', amount: 0 },
      models: []
    };
    selectedModelValue = {
      model_id: `mock-${capability}-v1`,
      cost_profile: { type: 'per_job', amount: 0 }
    };
    cost = { known: true, amount: 0, rule: 'dry_run' };
  } else {
    const eligible = eligibleProviders(capability);
    const proposedProviderId = text(proposed.selected_provider_id).toLowerCase();
    selectedProvider = eligible.find((provider) => provider.provider_id === proposedProviderId) || eligible[0];

    if (!selectedProvider) {
      hardBlockers.push(`NO_PROVIDER_FOR_CAPABILITY:${capability}:${job.job_id}`);
      selectedProvider = null;
    } else {
      if (proposedProviderId && proposedProviderId !== selectedProvider.provider_id) {
        sanitizationLog.push({
          path: `${job.job_id}.selected_provider_id`,
          reasons: ['UNAUTHORIZED_OR_INCOMPATIBLE_PROVIDER_REPLACED']
        });
      }

      selectedModelValue = selectedModel(
        selectedProvider,
        capability,
        text(proposed.selected_model_id)
      );

      const fallbackCandidates = eligible
        .filter((provider) => provider.provider_id !== selectedProvider.provider_id);

      const proposedFallbacks = unique(list(proposed.fallback_provider_ids).map((id) => text(id).toLowerCase()));
      fallbackProviders = [
        ...proposedFallbacks
          .map((id) => fallbackCandidates.find((provider) => provider.provider_id === id))
          .filter(Boolean),
        ...fallbackCandidates
      ];

      const maximumFallbacks = Number(brief.execution_policy?.default_fallback_count || 1);
      fallbackProviders = unique(fallbackProviders.map((provider) => provider.provider_id))
        .slice(0, maximumFallbacks);

      const costProfile = selectedModelValue?.cost_profile &&
        Object.keys(obj(selectedModelValue.cost_profile)).length
        ? selectedModelValue.cost_profile
        : selectedProvider.cost_profile;
      cost = costFromProfile(costProfile, job);

      if (
        brief.execution_policy?.require_credentials_before_dispatch &&
        brief.execution_policy?.dispatch_requested &&
        !text(selectedProvider.credential_ref_name)
      ) {
        hardBlockers.push(`MISSING_CREDENTIAL_REFERENCE:${selectedProvider.provider_id}:${job.job_id}`);
      }

      if (
        brief.execution_policy?.require_adapter_before_dispatch &&
        brief.execution_policy?.dispatch_requested &&
        !text(selectedProvider.adapter_workflow_id)
      ) {
        hardBlockers.push(`MISSING_ADAPTER_WORKFLOW:${selectedProvider.provider_id}:${job.job_id}`);
      }
    }
  }

  const maxAttempts = dryRun
    ? 1
    : clampInt(
        proposed.max_attempts,
        Number(brief.execution_policy?.default_max_attempts || 3),
        1,
        Number(brief.execution_policy?.default_max_attempts || 3)
      );

  const timeoutSeconds = dryRun
    ? 30
    : clampInt(
        proposed.timeout_seconds,
        Number(brief.execution_policy?.default_timeout_seconds || 420),
        30,
        Number(brief.execution_policy?.default_timeout_seconds || 420) * 2
      );

  resolvedJobs.push({
    job_key: `${text(base.ccg_context?.idempotency_key)}:CCG-80:${job.job_id}`,
    job_id: job.job_id,
    job_type: job.job_type,
    category: job.category,
    source_module: job.source_module,
    provider_capability: capability,
    production_id: job.production_id,
    scene_id: job.scene_id,
    frame_id: job.frame_id,
    asset_id: job.asset_id,
    dependencies: list(job.dependencies),
    selected_provider: selectedProvider ? {
      provider_id: selectedProvider.provider_id,
      display_name: selectedProvider.display_name,
      adapter_workflow_id: text(selectedProvider.adapter_workflow_id),
      credential_ref_name: text(selectedProvider.credential_ref_name),
      region: text(selectedProvider.region)
    } : null,
    selected_model_id: text(selectedModelValue?.model_id),
    fallback_provider_ids: fallbackProviders,
    priority: clampInt(proposed.priority, Number(job.priority || 50), 1, 1000),
    retry_policy: {
      max_attempts: maxAttempts,
      backoff_strategy: 'exponential_jitter',
      initial_delay_seconds: 2,
      maximum_delay_seconds: 60,
      retryable_classes: [
        'rate_limit',
        'provider_timeout',
        'transient_network',
        'provider_5xx'
      ],
      non_retryable_classes: [
        'invalid_input',
        'policy_block',
        'rights_block',
        'budget_exceeded',
        'authentication_error'
      ]
    },
    timeout_seconds: timeoutSeconds,
    concurrency_group: text(proposed.concurrency_group, capability),
    max_concurrency: selectedProvider
      ? Number(selectedProvider.max_concurrency || brief.execution_policy?.default_concurrency || 1)
      : Number(brief.execution_policy?.default_concurrency || 1),
    cost_estimate: {
      known: cost.known,
      amount: Number(cost.amount.toFixed(6)),
      currency: text(proposed.currency, brief.execution_policy?.currency || 'USD'),
      rule: cost.rule
    },
    input: job.input,
    output_spec: job.output_spec,
    verification_required: list(job.verification_required),
    dispatch_mode: dryRun ? 'DRY_RUN_SIMULATION' : 'ADAPTER_WORKFLOW',
    provider: text(selectedProvider?.provider_id, dryRun ? 'mock' : 'unresolved'),
    provider_id: text(selectedProvider?.provider_id, dryRun ? 'mock' : 'unresolved'),
    provider_job_id: '',
    capability,
    attempt: 0,
    attempts: 0,
    max_revisions: Number(job.max_revisions || brief.execution_policy?.max_revisions || 0),
    estimated_cost: Number(cost.amount || 0),
    expected_artifacts: list(job.expected_artifacts),
    status: dryRun ? 'PLANNED' : 'PLANNED',
    execute_in: 'PROVIDER_ADAPTER'
  });
}

const graph = topologicalStages(resolvedJobs);
for (const missing of graph.missing) {
  hardBlockers.push(`MISSING_DEPENDENCY:${missing.job_id}:${missing.dependency_id}`);
}
if (graph.cycle_ids.length) {
  hardBlockers.push(`DEPENDENCY_CYCLE:${graph.cycle_ids.join(',')}`);
}

const jobById = new Map(resolvedJobs.map((job) => [job.job_id, job]));
const executionStages = graph.stages.map((jobIds, stageIndex) => {
  const groups = {};
  for (const jobId of jobIds) {
    const job = jobById.get(jobId);
    const providerId = text(job.selected_provider?.provider_id, 'unresolved');
    const groupKey = `${providerId}:${job.concurrency_group}`;
    if (!groups[groupKey]) {
      groups[groupKey] = {
        group_id: groupKey,
        provider_id: providerId,
        concurrency_group: job.concurrency_group,
        max_concurrency: job.max_concurrency,
        job_ids: []
      };
    }
    groups[groupKey].job_ids.push(jobId);
  }

  return {
    stage_id: `stage-${String(stageIndex + 1).padStart(2, '0')}`,
    stage_index: stageIndex + 1,
    depends_on_stage_ids: stageIndex ? [`stage-${String(stageIndex).padStart(2, '0')}`] : [],
    job_ids: jobIds,
    dispatch_groups: Object.values(groups),
    completion_policy: 'ALL_JOBS_SUCCESS_OR_APPROVED_FALLBACK'
  };
});

const knownCosts = resolvedJobs
  .filter((job) => job.cost_estimate.known)
  .reduce((sum, job) => sum + Number(job.cost_estimate.amount || 0), 0);
const unresolvedCostJobs = resolvedJobs
  .filter((job) => !job.cost_estimate.known)
  .map((job) => job.job_id);
const maximumJobs = Number(brief.execution_policy?.max_jobs || brief.execution_policy?.maximum_jobs || 0);
const maximumRevisions = Number(brief.execution_policy?.max_revisions || 0);
const maximumCostConfigured = brief.execution_policy?.max_cost_configured === true || (brief.execution_policy?.maximum_cost !== undefined && brief.execution_policy?.maximum_cost !== null);
const maximumCost = maximumCostConfigured ? Number(brief.execution_policy?.max_cost ?? brief.execution_policy?.maximum_cost) : null;

if (!dryRun && maximumCost > 0 && knownCosts > maximumCost + 1e-9) {
  hardBlockers.push(`BUDGET_EXCEEDED:${knownCosts.toFixed(6)}>${maximumCost.toFixed(6)}`);
}

if (
  !dryRun &&
  brief.execution_policy?.dispatch_requested &&
  brief.execution_policy?.require_known_cost_before_dispatch &&
  unresolvedCostJobs.length
) {
  hardBlockers.push(`UNRESOLVED_COST:${unresolvedCostJobs.join(',')}`);
} else if (!dryRun && unresolvedCostJobs.length) {
  reviewReasons.push(`${unresolvedCostJobs.length} job(s) possuem custo ainda não resolvido.`);
}

const adapterWorkflowIds = unique(
  resolvedJobs
    .map((job) => text(job.selected_provider?.adapter_workflow_id))
    .filter(Boolean)
);

let executionAction = 'PLAN_ONLY';
if (dryRun) {
  executionAction = 'DRY_RUN_PLAN_ONLY';
} else if (brief.execution_policy?.dispatch_requested) {
  executionAction = hardBlockers.length
    ? 'DISPATCH_BLOCKED'
    : 'READY_FOR_ADAPTER_ORCHESTRATOR';
} else {
  executionAction = 'READY_FOR_MANUAL_OR_AUTOMATED_DISPATCH';
}

if (sanitizationLog.length) {
  reviewReasons.push(`${sanitizationLog.length} decisão(ões) de roteamento foram sanitizadas.`);
}

let productionStatus = 'READY';
let routingDecision = 'PROCEED';
let nextModule = 'CCG-90';

if (unique(hardBlockers).length) {
  productionStatus = 'BLOCKED';
  routingDecision = 'HOLD_FOR_REVIEW';
  nextModule = 'CCG-REVIEW';
} else if (unique(reviewReasons).length) {
  productionStatus = 'NEEDS_REVIEW';
  routingDecision = 'PROCEED_WITH_GUARDRAILS';
}

const now = new Date().toISOString();
const productionManifest = {
  manifest_version: '1.0.0',
  mode,
  execution_action: executionAction,
  execution_policy: {
    dispatch_requested: brief.execution_policy?.dispatch_requested === true,
    adapter_orchestrator_workflow_id: text(brief.execution_policy?.adapter_orchestrator_workflow_id),
    adapter_workflow_ids: adapterWorkflowIds,
    allowed_providers: list(brief.execution_policy?.allowed_providers || brief.allowed_provider_ids),
    max_jobs: maximumJobs,
    max_revisions: maximumRevisions,
    max_cost: maximumCost,
    max_cost_configured: maximumCostConfigured,
    require_human_approval: brief.execution_policy?.require_human_approval !== false,
    publish_allowed: false,
    publish_requested: false
  },
  provider_registry: dryRun
    ? [{
        provider_id: 'mock',
        display_name: 'Mock deterministic provider',
        capabilities: unique(resolvedJobs.map((job) => job.provider_capability)),
        adapter_workflow_id: '',
        credential_ref_name: '',
        max_concurrency: Number(brief.execution_policy?.default_concurrency || 1),
        status: 'SIMULATED'
      }]
    : list(brief.provider_catalog).map((provider) => ({
        provider_id: provider.provider_id,
        display_name: provider.display_name,
        capabilities: list(provider.capabilities),
        adapter_workflow_id: provider.adapter_workflow_id,
        credential_ref_name: provider.credential_ref_name,
        max_concurrency: provider.max_concurrency,
        status: provider.enabled && provider.allowed ? 'ELIGIBLE' : 'NOT_ELIGIBLE'
      })),
  jobs: resolvedJobs,
  execution_stages: executionStages,
  dependency_graph: {
    job_ids: resolvedJobs.map((job) => job.job_id),
    edges: resolvedJobs.flatMap((job) =>
      job.dependencies.map((dependencyId) => ({
        from_job_id: dependencyId,
        to_job_id: job.job_id
      }))
