          evidence_refs: finalOutputs.map((artifact) => text(artifact.artifact_id))
        }
      ],
      human_review_checklist: [
        'Abrir e revisar todos os masters e previews.',
        'Conferir copy visível e locução contra os registros aprovados.',
        'Conferir preços, condições, CTA e disclaimers.',
        'Conferir integridade do logo e identidade visual.',
        'Conferir naturalidade de pessoas, pele, mãos e anatomia.',
        'Conferir sincronização de áudio, legendas e transições.',
        'Confirmar direitos, consentimentos, licenças e recibos.',
        'Aprovar, solicitar revisão ou rejeitar cada saída final.'
      ],
      recommended_decision: 'REVIEW_REQUIRED',
      release_notes: [
        'Pacote de dry-run com artifacts simulados.',
        'Nenhuma publicação foi realizada.',
        'Aprovação humana continua obrigatória.'
      ],
      review: {
        required: true,
        reasons: ['Dry-run não substitui validação de artifacts reais.']
      }
    },
    ccg90_generation_mode: 'DETERMINISTIC_DRY_RUN'
  },
  binary: item.binary
}];

parameters.text:
=Crie a síntese de revisão do pacote e retorne SOMENTE o JSON exigido pelo parser.

Content package brief fechado:
{{ JSON.stringify($json.content_package_brief) }}

parameters.jsCode:
const incomingItem = $input.first();
const incoming = incomingItem.json || {};

let preparedItem = incomingItem;
try {
  preparedItem = $('CCG-90 Prepare Evidence & Package Brief').first();
} catch {}

const base = preparedItem.json || incoming;
const request = base.production_request || {};
const brief = base.content_package_brief || {};

const text = (value, fallback = '') => value === undefined || value === null ? fallback : String(value).trim();
const list = (value) => Array.isArray(value) ? value : [];
const obj = (value) => value && typeof value === 'object' && !Array.isArray(value) ? value : {};
const unique = (values) => [...new Set(values.map((value) => text(value)).filter(Boolean))];

function unwrap(value) {
  if (value?.content_package_review_proposal) return value;
  if (value?.output && typeof value.output === 'object') return value.output;
  for (const candidate of [value?.text, value?.output]) {
    if (typeof candidate === 'string') {
      try { return JSON.parse(candidate); } catch {}
    }
  }
  return value || {};
}

function canonical(value) {
  if (Array.isArray(value)) return value.map(canonical);
  if (value && typeof value === 'object') {
    return Object.keys(value).sort().reduce((acc, key) => {
      acc[key] = canonical(value[key]);
      return acc;
    }, {});
  }
  return value;
}

function fnv(value) {
  const source = JSON.stringify(canonical(value));
  let hash = 2166136261;
  for (let index = 0; index < source.length; index++) {
    hash ^= source.charCodeAt(index);
    hash = Math.imul(hash, 16777619);
  }
  return (hash >>> 0).toString(16).padStart(8, '0');
}

function clean(value) {
  return text(value)
    .replace(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi, '[EMAIL_REDACTED]')
    .replace(/(?:\+?55\s*)?(?:\(?\d{2}\)?\s*)?(?:9?\d{4})[-.\s]?\d{4}/g, '[PHONE_REDACTED]')
    .replace(/\b\d{3}\.?\d{3}\.?\d{3}-?\d{2}\b/g, '[CPF_REDACTED]');
}

function statusPass(value) {
  return ['PASS', 'PASSED', 'APPROVED', 'VALIDATED', 'COMPLETED'].includes(text(value).toUpperCase());
}

function statusFail(value) {
  return ['FAIL', 'FAILED', 'REJECTED', 'BLOCKED', 'FAILED_BLOCKING', 'POLICY_BLOCKED', 'CANCELLED', 'NEEDS_REVIEW'].includes(text(value).toUpperCase());
}

const parsed = unwrap(incoming);
const proposal = obj(parsed.content_package_review_proposal || incoming.content_package_review_proposal);
const dryRun = text(brief.mode) === 'DRY_RUN';

const reviewReasons = [
  ...list(base.ccg90_input_validation?.warnings),
  ...list(brief.upstream_review?.reasons),
  ...list(proposal.review?.reasons)
];
const hardBlockers = [];
const packageWarnings = [];
const executionJobs = list(brief.execution?.jobs);
const noResults = executionJobs.length === 0;
const jobResultMap = new Map(executionJobs.map((result) => [text(result.job_id), result]));
const expectedJobs = list(brief.production_manifest?.jobs);
const terminalSuccesses = new Set(list(brief.package_policy?.terminal_success_statuses).map((status) => text(status).toUpperCase()));
const blockingStatuses = new Set(list(brief.package_policy?.blocking_failure_statuses).map((status) => text(status).toUpperCase()));
let executionPending = ['PLANNED', 'RUNNING'].includes(text(brief.execution?.execution_status || brief.execution?.status).toUpperCase());
const executionStatus = text(brief.execution?.execution_status || brief.execution?.status).toUpperCase();
const awaitingExecution = !dryRun && (noResults || executionPending);

const jobEvidence = expectedJobs.map((job) => {
  const result = jobResultMap.get(text(job.job_id));
  const status = text(result?.status).toUpperCase();
  const missing = !result;
  const blocking = result && (blockingStatuses.has(status) || statusFail(status));
  const complete = result && terminalSuccesses.has(status);

  if (missing && !dryRun && !noResults) hardBlockers.push(`MISSING_JOB_RESULT:${text(job.job_id)}`);
  if (blocking) hardBlockers.push(`BLOCKING_JOB_STATUS:${text(job.job_id)}:${status}`);
  if (result && ['PLANNED', 'RUNNING'].includes(status)) executionPending = true;
  if (result && !complete && !blocking && !['PLANNED', 'RUNNING'].includes(status)) {
    hardBlockers.push(`NON_TERMINAL_JOB_STATUS:${text(job.job_id)}:${status || 'EMPTY'}`);
  }

  if (
    result &&
    brief.package_policy?.all_costs_must_be_recorded &&
    result.cost?.recorded !== true
  ) {
    hardBlockers.push(`COST_NOT_RECORDED:${text(job.job_id)}`);
  }

  if (
    result &&
    brief.package_policy?.provider_receipts_required &&
    !text(result.provider_receipt_id)
  ) {
    hardBlockers.push(`MISSING_PROVIDER_RECEIPT:${text(job.job_id)}`);
  }

  const qaStatus = text(result?.qa?.status).toUpperCase();
  if (qaStatus && statusFail(qaStatus)) {
    hardBlockers.push(`JOB_QA_FAILED:${text(job.job_id)}`);
  } else if (qaStatus && !statusPass(qaStatus)) {
    packageWarnings.push(`JOB_QA_WARNING:${text(job.job_id)}:${qaStatus}`);
  }

  return {
    job_id: text(job.job_id),
    job_key: text(job.job_key),
    job_type: text(job.job_type),
    category: text(job.category),
    production_id: text(job.production_id),
    expected: true,
    result_received: Boolean(result),
    status,
    complete,
    attempt: Number(result?.attempt || result?.attempts || 0),
    attempts: Number(result?.attempts || result?.attempt || 0),
    provider: text(result?.provider || result?.provider_id),
    provider_id: text(result?.provider || result?.provider_id),
    provider_job_id: text(result?.provider_job_id || result?.provider_receipt_id),
    model_id: text(result?.model_id),
    cost: obj(result?.cost),
    provider_receipt_id: text(result?.provider_receipt_id || result?.provider_job_id),
    started_at: text(result?.started_at),
    finished_at: text(result?.finished_at),
    qa: obj(result?.qa),
    error: result?.error || null
  };
});

const artifacts = list(brief.artifact_registry);
const artifactByKey = new Map();
const artifactsByJob = new Map();

for (const artifact of artifacts) {
  const key = text(artifact.artifact_key);
  if (key) artifactByKey.set(key, artifact);
  const jobId = text(artifact.source_job_id);
  if (!artifactsByJob.has(jobId)) artifactsByJob.set(jobId, []);
  artifactsByJob.get(jobId).push(artifact);
}

function metadataMatches(specValue, metadataValue) {
  const spec = obj(specValue);
  const metadata = obj(metadataValue);
  const mismatches = [];

  for (const key of ['width', 'height', 'fps', 'sample_rate_hz', 'bit_depth']) {
    if (spec[key] !== undefined && metadata[key] !== undefined && Number(spec[key]) !== Number(metadata[key])) {
      mismatches.push(`${key}:${metadata[key]}!=${spec[key]}`);
    }
  }

  if (spec.duration_seconds !== undefined && metadata.duration_seconds !== undefined) {
    if (Math.abs(Number(spec.duration_seconds) - Number(metadata.duration_seconds)) > 0.12) {
      mismatches.push(`duration_seconds:${metadata.duration_seconds}!=${spec.duration_seconds}`);
    }
  }

  for (const key of ['container', 'format', 'color_space', 'pixel_format', 'video_codec', 'audio_codec']) {
    if (
      spec[key] !== undefined &&
      metadata[key] !== undefined &&
      text(spec[key]).toLowerCase() !== text(metadata[key]).toLowerCase()
    ) {
      mismatches.push(`${key}:${metadata[key]}!=${spec[key]}`);
    }
  }

  return mismatches;
}

const artifactEvidence = list(brief.expected_artifacts).map((expectation) => {
  const direct = artifactByKey.get(text(expectation.artifact_key));
  const candidates = list(artifactsByJob.get(text(expectation.source_job_id)));
  const artifact = direct || candidates[0];
  const missing = !artifact;

  if (missing && !awaitingExecution) {
    hardBlockers.push(`MISSING_ARTIFACT:${text(expectation.artifact_key)}:${text(expectation.source_job_id)}`);
  }

  const checksum = obj(artifact?.checksum);
  const checksumValid = Boolean(text(checksum.value));
  if (artifact && !dryRun && (checksum.simulated === true || obj(artifact.metadata).simulated === true)) {
    hardBlockers.push(`SIMULATED_ARTIFACT_IN_LIVE:${text(expectation.artifact_key)}`);
  }
  if (artifact && (artifact.checksum_valid === false || (artifact.sha256 && checksum.value && artifact.sha256 !== checksum.value))) hardBlockers.push(`CHECKSUM_DIVERGENCE:${text(expectation.artifact_key)}`);
  if (artifact && expectation.checksum_required && !checksumValid) {
    hardBlockers.push(`MISSING_CHECKSUM:${text(expectation.artifact_key)}`);
  }

  const metadata = obj(artifact?.metadata);
  const metadataPresent = Object.keys(metadata).length > 0;
  if (artifact && expectation.metadata_required && !metadataPresent) {
    hardBlockers.push(`MISSING_ARTIFACT_METADATA:${text(expectation.artifact_key)}`);
  }

  if (artifact && !text(artifact.uri) && !text(artifact.binary_key)) {
    hardBlockers.push(`MISSING_ARTIFACT_LOCATOR:${text(expectation.artifact_key)}`);
  }

  if (artifact && !dryRun && Number(artifact.file_size_bytes || 0) <= 0) {
    hardBlockers.push(`INVALID_ARTIFACT_SIZE:${text(expectation.artifact_key)}`);
  }

  const mismatches = artifact ? metadataMatches(expectation.expected_output_spec, metadata) : [];
  if (mismatches.length) {
    const isFinal = text(expectation.category) === 'FINAL_RENDER';
    const code = `ARTIFACT_SPEC_MISMATCH:${text(expectation.artifact_key)}:${mismatches.join(',')}`;
    if (isFinal) hardBlockers.push(code);
    else packageWarnings.push(code);
  }

  const qaStatus = text(artifact?.qa?.status).toUpperCase();
  if (qaStatus && statusFail(qaStatus)) {
    hardBlockers.push(`ARTIFACT_QA_FAILED:${text(expectation.artifact_key)}`);
  } else if (qaStatus && !statusPass(qaStatus)) {
    packageWarnings.push(`ARTIFACT_QA_WARNING:${text(expectation.artifact_key)}:${qaStatus}`);
  }

  return {
    artifact_key: text(expectation.artifact_key),
    artifact_id: text(artifact?.artifact_id),
    source_job_id: text(expectation.source_job_id),
    production_id: text(expectation.production_id),
    category: text(expectation.category),
    expected_output_spec: obj(expectation.expected_output_spec),
    present: Boolean(artifact),
    uri: text(artifact?.uri),
    binary_key: text(artifact?.binary_key),
    mime_type: text(artifact?.mime_type),
    file_size_bytes: Number(artifact?.file_size_bytes || 0),
    checksum,
    checksum_valid: checksumValid,
    metadata,
    metadata_present: metadataPresent,
    metadata_mismatches: mismatches,
    qa: obj(artifact?.qa),
    simulated: checksum.simulated === true || metadata.simulated === true
  };
});

const finalRenderJobIds = new Set(list(brief.final_render_job_ids));
const finalOutputIndex = artifactEvidence
  .filter((artifact) => artifact.present && finalRenderJobIds.has(artifact.source_job_id))
  .map((artifact) => ({
    output_id: artifact.artifact_key,
    artifact_id: artifact.artifact_id,
    source_job_id: artifact.source_job_id,
    production_id: artifact.production_id,
    uri: artifact.uri,
    binary_key: artifact.binary_key,
    mime_type: artifact.mime_type,
    checksum: artifact.checksum,
    metadata: artifact.metadata,
    preview_uri: text(artifact.metadata?.preview_uri),
    simulated: artifact.simulated,
    review_status: 'PENDING_HUMAN_REVIEW'
  }));

if (
  !awaitingExecution &&
  brief.package_policy?.all_final_render_jobs_must_complete &&
  finalOutputIndex.length < finalRenderJobIds.size
) {
  hardBlockers.push(`FINAL_OUTPUT_COUNT_MISMATCH:${finalOutputIndex.length}/${finalRenderJobIds.size}`);
}

function validateChecks(checks, family) {
  const items = list(checks);
  if (!items.length) return { total: 0, passed: 0, failed: 0, missing: true };
  let passed = 0;
  let failed = 0;
  for (const check of items) {
    if (statusPass(check.status)) passed += 1;
    else if (statusFail(check.status)) {
      failed += 1;
      hardBlockers.push(`${family}_CHECK_FAILED:${text(check.check_id || check.subject_id)}`);
    } else {
      packageWarnings.push(`${family}_CHECK_UNRESOLVED:${text(check.check_id || check.subject_id)}`);
    }
  }
  return { total: items.length, passed, failed, missing: false };
}

const rightsSummary = validateChecks(brief.execution?.rights_checks, 'RIGHTS');
const licenseSummary = validateChecks(brief.execution?.license_checks, 'LICENSE');
const consentSummary = validateChecks(brief.execution?.consent_checks, 'CONSENT');

if (
  !awaitingExecution &&
  brief.package_policy?.all_rights_and_license_checks_must_pass &&
  !dryRun &&
  (rightsSummary.missing || licenseSummary.missing)
) {
  hardBlockers.push('RIGHTS_OR_LICENSE_EVIDENCE_MISSING');
}

const qaSummaryStatus = text(brief.execution?.qa_summary?.status).toUpperCase();
if (qaSummaryStatus && statusFail(qaSummaryStatus)) {
  hardBlockers.push('GLOBAL_QA_FAILED');
} else if (qaSummaryStatus && !statusPass(qaSummaryStatus)) {
  packageWarnings.push(`GLOBAL_QA_UNRESOLVED:${qaSummaryStatus}`);
}

const expectedCurrency = text(brief.production_manifest?.budget?.currency, brief.execution?.currency || 'USD');
const actualCosts = jobEvidence.reduce((sum, job) => sum + Number(job.cost?.amount || 0), 0);
const costCurrencies = unique(jobEvidence.map((job) => text(job.cost?.currency)).filter(Boolean));

if (costCurrencies.length > 1 || (costCurrencies.length === 1 && costCurrencies[0] !== expectedCurrency)) {
  packageWarnings.push(`CURRENCY_MISMATCH:${costCurrencies.join(',')}:${expectedCurrency}`);
}

const maximumCostConfigured = brief.production_manifest?.budget?.max_cost_configured === true || (brief.production_manifest?.budget?.maximum_cost !== undefined && brief.production_manifest?.budget?.maximum_cost !== null);
const maximumCost = maximumCostConfigured ? Number(brief.production_manifest?.budget?.max_cost ?? brief.production_manifest?.budget?.maximum_cost) : null;
const executorTotalCost = Number(brief.execution?.totals?.cost ?? actualCosts);
if (maximumCostConfigured && executorTotalCost > maximumCost + 1e-9) {
  hardBlockers.push(`ACTUAL_BUDGET_EXCEEDED:${actualCosts.toFixed(6)}>${maximumCost.toFixed(6)}`);
}

if (!dryRun && text(brief.execution?.mode).toUpperCase() === 'DRY_RUN') {
  hardBlockers.push('DRY_RUN_EXECUTION_RESULTS_IN_LIVE');
}

reviewReasons.push(...packageWarnings);
if (dryRun) reviewReasons.push('Dry-run utiliza artifacts e recibos simulados.');
if (brief.upstream_review?.required) reviewReasons.push('Um ou mais módulos anteriores já exigiam revisão.');

let packageStatus = 'READY_FOR_HUMAN_REVIEW';
let routingDecision = 'REVIEW_REQUIRED';
let nextModule = 'CCG-REVIEW';

if (awaitingExecution) {
  packageStatus = 'AWAITING_EXECUTION';
  routingDecision = 'WAIT_FOR_EXECUTION';
  nextModule = 'CCG-80-EXECUTION';
} else if (unique(hardBlockers).length) {
  packageStatus = 'BLOCKED';
  routingDecision = 'HOLD_FOR_REVIEW';
  nextModule = 'CCG-REVIEW';
} else if (dryRun) {
  packageStatus = 'DRY_RUN_COMPLETE';
  routingDecision = 'REVIEW_REQUIRED';
}

const allowedRecommended = new Set(['REVIEW_REQUIRED', 'WAIT_FOR_EXECUTION', 'BLOCKED']);
let recommendedDecision = text(proposal.recommended_decision).toUpperCase();
if (!allowedRecommended.has(recommendedDecision)) recommendedDecision = routingDecision;
if (awaitingExecution) recommendedDecision = 'WAIT_FOR_EXECUTION';
if (unique(hardBlockers).length) recommendedDecision = 'BLOCKED';

const humanChecklist = unique([
  ...list(proposal.human_review_checklist).map(clean),
  'Abrir e revisar todos os masters e previews.',
  'Conferir copy, preços, CTA e disclaimers contra os registros aprovados.',
  'Conferir logo, identidade visual, legibilidade e naturalidade.',
  'Conferir áudio, legendas, sincronização e níveis.',
  'Confirmar direitos, licenças, consentimentos, custos e recibos.',
  'Registrar decisão humana por saída: aprovar, revisar ou rejeitar.'
]);

const reviewPriorities = list(proposal.review_priorities).slice(0, 12).map((priority, index) => ({
  priority: Number(priority.priority || index + 1),
  area: clean(priority.area),
  instruction: clean(priority.instruction),
  evidence_refs: unique(list(priority.evidence_refs))
}));

const qaReport = {
  status: awaitingExecution ? 'PENDING' : unique(hardBlockers).length ? 'FAIL' : packageWarnings.length ? 'WARN' : 'PASS',
  structural: {
    expected_jobs: expectedJobs.length,
    job_results_received: jobResultMap.size,
    completed_jobs: jobEvidence.filter((job) => job.complete).length,
    expected_artifacts: artifactEvidence.length,
    present_artifacts: artifactEvidence.filter((artifact) => artifact.present).length,
    final_outputs: finalOutputIndex.length
  },
  integrity: {
    artifacts_with_checksums: artifactEvidence.filter((artifact) => artifact.checksum_valid).length,
    artifacts_with_metadata: artifactEvidence.filter((artifact) => artifact.metadata_present).length,
    simulated_artifacts: artifactEvidence.filter((artifact) => artifact.simulated).length
  },
  compliance: {
    rights: rightsSummary,
    licenses: licenseSummary,
    consents: consentSummary,
    global_qa_status: qaSummaryStatus || 'NOT_REPORTED'
  },
  financial: {
    actual_cost: Number(executorTotalCost.toFixed(6)),
    maximum_cost: maximumCost,
    currency: expectedCurrency,
    within_budget: !maximumCostConfigured || executorTotalCost <= maximumCost + 1e-9,
    all_required_costs_recorded: !brief.package_policy?.all_costs_must_be_recorded ||
      jobEvidence.every((job) => job.cost?.recorded === true)
  },
  warnings: unique(packageWarnings),
  blockers: unique(hardBlockers)
};

const corePackage = {
  execution_status: executionStatus || (dryRun ? 'COMPLETED' : 'PLANNED'),
  package_version: '1.0.0',
  package_id: text(brief.package_id),
  run_id: text(brief.run_id),
  production_id: text(brief.production_id),
  campaign_id: text(brief.campaign_id),
  content_id: text(brief.content_id),
  mode: text(brief.mode),
  request_summary: obj(brief.request_summary),
  package_status: packageStatus,
  routing_decision: routingDecision,
  next_module: nextModule,
  executive_summary: clean(
    proposal.executive_summary ||
    `Pacote ${packageStatus.toLowerCase()} com ${finalOutputIndex.length} saída(s) final(is).`
  ),
  module_registry: list(brief.module_registry),
  execution_summary: {
    execution_id: text(brief.execution?.execution_id),
    started_at: text(brief.execution?.started_at),
    finished_at: text(brief.execution?.finished_at),
    jobs: jobEvidence,
    totals: { ...obj(brief.execution?.totals), cost: executorTotalCost, currency: text(brief.execution?.currency || 'USD') },
    receipts: list(brief.execution?.receipts),
    checkpoint: obj(brief.execution?.checkpoint)
  },
  artifact_registry: artifactEvidence,
  final_output_index: finalOutputIndex,
  qa_report: qaReport,
  evidence_manifests: {
    rights_checks: list(brief.execution?.rights_checks),
    license_checks: list(brief.execution?.license_checks),
    consent_checks: list(brief.execution?.consent_checks),
    global_qa: obj(brief.execution?.qa_summary),
    binary_inventory: list(brief.binary_inventory)
  },
  review_packet: {
    required: true,
    recommended_decision: recommendedDecision,
    priorities: reviewPriorities,
    checklist: humanChecklist,
    release_notes: unique(list(proposal.release_notes).map(clean)),
    decision_options: [
      'APPROVE_FOR_MANUAL_RELEASE',
      'REQUEST_REVISION',
      'REJECT'
    ],
    approval_record: null
  },
  publication_gate: {
    publish_requested: false,
    publish_allowed: false,
    published: false,
    human_approval_required: true,
    automatic_publication_forbidden: true
  },
  review: {
    required: true,
    reasons: unique(reviewReasons),
    hard_blockers: unique(hardBlockers)
  },
  generated_at: text(
    brief.execution?.finished_at,
    text(brief.production_manifest?.manifested_at, text(base.ccg_context?.accepted_at, new Date().toISOString()))
  )
};

const evidenceSealCore = {
  package_id: corePackage.package_id,
  run_id: corePackage.run_id,
  production_id: corePackage.production_id,
  campaign_id: corePackage.campaign_id,
  content_id: corePackage.content_id,
  mode: corePackage.mode,
  package_status: corePackage.package_status,
  module_registry: corePackage.module_registry,
  execution_summary: corePackage.execution_summary,
  artifact_registry: corePackage.artifact_registry,
  final_output_index: corePackage.final_output_index,
  qa_report: corePackage.qa_report,
  evidence_manifests: corePackage.evidence_manifests,
  publication_gate: corePackage.publication_gate
};

const packageSeal = {
  algorithm: 'FNV1A32',
  value: fnv(evidenceSealCore),
  sealed_at: new Date().toISOString(),
  scope: 'EVIDENCE_CORE_EXCLUDING_REVIEW_NARRATIVE',
  evidence_hashes: list(brief.module_registry).map((entry) => ({
    module: entry.module,
    value: entry.integrity?.value
  }))
};

const contentPackage = {
  ...corePackage,
  package_seal: packageSeal
};

const now = new Date().toISOString();
const priorOutputs = obj(base.module_outputs);
const priorTrace = list(base.module_trace);
const moduleOutput = {
  status: 'DONE',
  output_type: 'CONTENT_PACKAGE',
  started_at: text(brief.prepared_at, now),
  finished_at: now,
  content_package: contentPackage
};

const event = {
  event_name: 'ccg.content_package.completed',
  event_version: '1.0.0',
  event_id: `${text(base.ccg_context?.run_id)}:CCG-90:${packageStatus.toLowerCase()}`,
  occurred_at: now,
  idempotency_key: `${text(base.ccg_context?.idempotency_key)}:CCG-90`,
  payload: {
    run_id: text(base.ccg_context?.run_id),
    production_id: text(request.production_id),
    campaign_id: text(request.campaign_id),
    content_id: text(request.content_id),
    package_id: contentPackage.package_id,
    package_status: packageStatus,
    routing_decision: routingDecision,
    next_module: nextModule,
    package_seal: packageSeal,
    counts: {
      jobs: jobEvidence.length,
      artifacts: artifactEvidence.length,
      final_outputs: finalOutputIndex.length,
      warnings: qaReport.warnings.length,
      blockers: qaReport.blockers.length
    },
    budget: qaReport.financial
  }
};

return [{
  json: {
    ...base,
    module_outputs: {
      ...priorOutputs,
      CCG_90: moduleOutput
    },
    module_trace: [
      ...priorTrace,
      {
        module: 'CCG-90',
        status: 'DONE',
        output_type: 'CONTENT_PACKAGE',
